#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeTargetSummary {
    native_len: i64,
    object_len: i64,
    link_response_len: i64,
    target_arch: i64,
    target_format: i64,
    linker_kind: i64,
    ir_len: i64,
    object_byte0: i64,
    object_byte4: i64,
    response_output_byte: i64,
    response_object_byte: i64,
    multi_response_object2_byte: i64,
    multi_link_response_len: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeBundleSummary {
    program_object_hash: i64,
    runtime_object_hash: i64,
    response_path_hash: i64,
    program_binary_hash: i64,
    response_text_hash: i64,
    response_text_len: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeObservationSummary {
    target: NativeTargetSummary,
    bundle: NativeBundleSummary,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeStageObservation {
    darwin: NativeObservationSummary,
    linux: NativeObservationSummary,
    aarch64: NativeObservationSummary,
}

#[derive(Debug)]
struct NativeHostArtifactBundle {
    program_object: Vec<u8>,
    runtime_object: Vec<u8>,
    response_text: String,
    program_binary: Vec<u8>,
    stdout: Vec<u8>,
    stderr: Vec<u8>,
    exit_code: i32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeHostExecutionResult {
    exit_code: i32,
    stdout: Vec<u8>,
    stderr: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeHostBundleObservation {
    program_object_hash: u64,
    runtime_object_hash: u64,
    response_text_hash: u64,
    program_binary_hash: u64,
    stdout_hash: u64,
    stderr_hash: u64,
    exit_code: i32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeEntrypointBundle {
    function_start_len: usize,
    main_func_idx: usize,
    declared_code_len: usize,
    declared_data_len: usize,
    entrypoint_offset: usize,
    code_bytes: Vec<u8>,
    data_bytes: Vec<u8>,
}

#[derive(Debug, Clone, Copy)]
struct NativeEntrypointLayout {
    function_start_len: usize,
    main_func_idx: usize,
    entrypoint_offset: usize,
}

struct NativeCodeDataTransport {
    declared_code_len: usize,
    code_bytes: Vec<u8>,
    declared_data_len: usize,
    data_bytes: Vec<u8>,
    layout: Option<NativeEntrypointLayout>,
}

fn actual_stage23_seed_source_with_payload_and_code_binding_and_target(
    payload_expr: &str,
    code_binding_expr: &str,
    target_expr: &str,
    main_body: &str,
) -> String {
    let source =
        selfhost_main_native_code_only_export_harness_with_payload_and_code_binding_and_target(
            payload_expr,
            code_binding_expr,
            target_expr,
            main_body,
        )
        .replacen("(module App.HarnessMain)", "(module App.Seed)", 1);
    strip_host_only_x86_file_segment_helpers(source)
}

fn strip_host_only_x86_file_segment_helpers(source: String) -> String {
    let Some(start) = source.find("(defn prefixed-chunk-file-path") else {
        return source;
    };
    let Some(relative_end) = source[start..].find("(defn remainder") else {
        return source;
    };
    let end = start + relative_end;
    format!("{}{}", &source[..start], &source[end..])
}

fn strip_linux_x86_unused_base64_helpers(source: String) -> String {
    let Some(start) = source.find("\n(defn str4") else {
        return source;
    };
    let Some(relative_end) = source[start..].find("\n(defn main []") else {
        return source;
    };
    let end = start + relative_end;
    format!("{}{}", &source[..start], &source[end..])
}

fn representative_actual_stage23_seed_source() -> String {
    representative_actual_stage23_seed_source_for_target("(host-target)")
}

