fn assert_shell_function_declares_locals(script: &str, function_name: &str, vars: &[&str]) {
    let body = shell_function_body(script, function_name);
    for var in vars {
        assert!(
            shell_function_declares_local(body, var),
            "{function_name} は再帰/chunk 実行の状態破壊を避けるため {var} を local 宣言するべき"
        );
    }
}

fn shell_function_body<'a>(script: &'a str, function_name: &str) -> &'a str {
    let marker = format!("{function_name}() {{");
    script
        .split(&marker)
        .nth(1)
        .and_then(|tail| tail.split("\n}\n").next())
        .unwrap_or_else(|| panic!("shell function {function_name} が見つからない"))
}

fn shell_function_declares_local(body: &str, var: &str) -> bool {
    body.lines().any(|line| {
        let trimmed = line.trim_start();
        trimmed == format!("local {var}")
            || trimmed.starts_with(&format!("local {var}="))
            || trimmed.starts_with(&format!("local {var} "))
    })
}

#[test]
fn test_linux_x86_file_segmented_harness_writes_segments_from_append_emit_vector() {
    let source =
        selfhost_main_native_code_only_export_harness_with_payload_and_code_binding_and_target(
            r#"(compile-file-functions-payload-with-cache (command-line-arg 1) 10 cache-ref parse-count-ref)"#,
            r#"entrypoint-func-idx (- (vector-length callables) 1)
                    starts (collect-callable-function-starts-x86 native-callables 10)
                    user-total (callable-user-total-size-x86 native-callables 10)
                    code-len (+ user-total (x86-selfhost-helper-trailer-size 10))
                    code (vector-new 0)
                    entrypoint-offset (vector-get starts (- entrypoint-func-idx 10))"#,
            "(make-target 3)",
            r#"      (let [main-func-idx entrypoint-func-idx
          data-len (vector-length data)
          code-chunk-count (write-x86-code-segments "code-bytes-" native-callables starts 10 user-total)
          data-chunk-count (write-packed-byte-chunks "data-bytes-" data 0 data-len 0)]
         (print code-chunk-count))"#,
        );

    let writer_step_body = source
        .split("(defn write-x86-function-code-segment-step")
        .nth(1)
        .and_then(|tail| {
            tail.split("(defn write-x86-function-code-segments-loop")
                .next()
        })
        .expect(
            "Linux x86 file segment seed に write-x86-function-code-segment-step が存在すること",
        );
    assert!(
        source.contains("(defn write-x86-function-code-segments-loop")
            && source.contains("(defn write-x86-function-code-segment-step")
            && writer_step_body.contains("result (ref-new (vector-new 0))")
            && writer_step_body.contains("layout (make-x86-function-emit-layout import-count import-stub-offset function-start 0)")
            && writer_step_body.contains("generate-native-function-x86-64-bundle-with-layout func-meta result starts functions layout")
            && writer_step_body.contains("segment (ref-get result)")
            && !writer_step_body.contains("segment (trim-preallocated-x86-segment raw-segment function-size)")
            && !writer_step_body.contains("result (ref-new (vector-new function-size))"),
        "Linux x86 file-segment writer は preallocated vector へ append せず、print path と同じ空 vector emit + declared slot padding を使うべき"
    );
}

#[test]
fn test_linux_x86_representative_seed_copy_slice_uses_bounded_steps() {
    let source = linux_x86_representative_actual_stage23_seed_source();

    assert!(
        source.contains("(defn copy-byte-slice-loop-bounded")
            && source.contains("(defn continue-copy-byte-slice-loop-step-64")
            && source.contains("out-ref (ref-new (vector-new 0))")
            && source.contains("idx-ref (ref-new idx)")
            && source.contains("remaining-ref (ref-new remaining)")
            && source.contains("(ref-set out-ref next)")
            && source.contains("(copy-byte-slice-loop-bounded out-ref src (+ (ref-get idx-ref) 1) end (- (ref-get remaining-ref) 1))")
            && source.contains("(continue-copy-byte-slice-loop-step-64 out-ref src end next-idx)"),
        "Linux x86 segmented seed の byte slice copy は stage1 native stack overflow を避けるため ref + 64 要素 bounded step で進めるべき"
    );
}

#[test]
fn test_linux_x86_representative_seed_releases_function_segment_before_next_segment() {
    let source = linux_x86_representative_actual_stage23_seed_source();
    let body = source
        .split("(defn print-x86-function-code-segments-loop")
        .nth(1)
        .and_then(|tail| tail.split("(defn print-x86-function-ir-prefix-loop").next())
        .expect("Linux x86 segmented seed に print-x86-function-code-segments-loop が存在すること");
    let print_pos = body
        .find("(print-packed-code-segment-with-length padded-segment function-size)")
        .expect("function segment を packed segment として出力すること");
    let recur_pos = body[print_pos..]
        .find("(print-x86-function-code-segments-loop functions starts import-count import-stub-offset (+ idx 1) len)")
        .map(|pos| print_pos + pos)
        .expect("function segment loop は次 segment へ進むこと");
    let release_pos = body[print_pos..recur_pos]
        .find("(root_pop)")
        .map(|pos| print_pos + pos)
        .expect("function segment loop は次 segment 再帰前に per-function root を解放すること");

    assert!(
        print_pos < release_pos && release_pos < recur_pos,
        "Linux x86 segmented seed は OOM を避けるため、segment 出力後に padded segment/result/layout 等を解放してから次 segment を生成するべき"
    );
}

#[test]
fn test_linux_x86_representative_seed_can_print_function_segment_metadata() {
    let source = linux_x86_representative_actual_stage23_seed_source();
    lsharp_syntax::parse(&source)
        .expect("Linux x86 segmented seed source は metadata helper 追加後も parse できること");
    assert!(
        source.contains("(defn print-x86-function-segment-metadata-loop [functions starts import-count import-stub-offset idx len prefix-limit]")
            && source.contains("metadata-mode (if (> (string-length (command-line-arg 6)) 0) 1 0)")
            && source.contains(
                "(print-x86-function-segment-metadata-loop native-callables starts 10 user-total range-start range-end metadata-prefix-limit)"
            )
            && source.contains("(print (native-function-param-count func-meta))")
            && source.contains("(print (native-function-local-count func-meta))")
            && source.contains("(print body-offset)")
            && source.contains("(print (vector-length ir-func))")
            && source.contains("(print 9000000289)")
            && source.contains("(print 9000000290)")
            && source.contains("(print 9000000291)")
            && source.contains("(print 9000000292)")
            && source.contains("(defn print-x86-function-ir-prefix-loop [segment ir offsets functions control-ctx idx len depth]")
            && source.contains("metadata-prefix-limit")
            && source.contains("command-line-arg 7")
            && source.contains("(print 9000000021)")
            && source.contains(
                "(let [final (print-x86-function-segment-metadata-loop functions starts import-count import-stub-offset (+ idx 1) len prefix-limit)]"
            ),
        "Linux x86 segmented seed は通常 transport を変えず、任意 range の function metadata を native stage1 実行から出せるべき"
    );
}

#[test]
fn test_linux_x86_representative_seed_can_print_stage_progress_markers() {
    let source = linux_x86_representative_actual_stage23_seed_source();
    lsharp_syntax::parse(&source)
        .expect("Linux x86 segmented seed source は progress helper 追加後も parse できること");

    for marker in [
        "9000000030",
        "9000000031",
        "9000000032",
        "9000000033",
        "9000000034",
        "9000000035",
        "9000000036",
        "9000000037",
        "9000000038",
        "9000000039",
        "9000000040",
        "9000000120",
        "9000000121",
    ] {
        assert!(
            source.contains(marker),
            "Linux x86 segmented seed は stage3 setup progress marker {marker} を出せるべき"
        );
    }

    for token in [
        "progress-mode (if (> (string-length (command-line-arg 8)) 0) 1 0)",
        "pre-payload-progress-mode",
        "pre-payload-progress-start",
        "pre-payload-progress-read",
        "read-file source-path",
        "string-length pre-payload-source",
        "string-char-at pre-payload-source 0",
        "compile-file-functions-payload-with-cache-progress source-path 10 cache-ref parse-count-ref",
        "progress-after-native-callables",
        "(print (vector-length functions))",
        "(print (vector-length callables))",
        "(print (+ 9 (vector-length functions)))",
        "progress-after-slot-sample",
        "slot-sample-start (if (= progress-mode 1)",
        "slot-sample-end-arg (if (= progress-mode 1)",
        "slot-sample-end (if (= slot-sample-end-arg 0) 4 slot-sample-end-arg)",
        "print-x86-slot-size-progress native-callables slot-sample-start slot-sample-end",
        "(defn print-x86-slot-size-progress",
        "(print sample-end)",
        "progress-after-starts",
        "progress-after-user-total",
        "starts-size-sample-idx slot-sample-start",
        "starts-size-sample-size (if (< starts-size-sample-start 0) -1 (- starts-size-sample-next starts-size-sample-start))",
        "(print 9000000120)",
        "(print starts-size-sample-size)",
        "(print 9000000121)",
        "progress-after-code-len",
        "(if (= progress-mode 1)",
        "(print 9000000038)",
        "(print entrypoint-offset)",
        "(print user-total)",
        "(print code-len)",
        "(print data-len)",
        "metadata-mode (if (> (string-length (command-line-arg 6)) 0) 1 0)",
    ] {
        assert!(
            source.contains(token),
            "Linux x86 segmented seed は通常/metadata transport を残したまま、arg8 で setup progress token {token} を含むべき"
        );
    }

    for token in [
        "print-x86-first-large-slot-size functions 0",
        "progress-after-payload-start",
        "progress-after-pairs-probe",
        "progress-after-compile-probe",
        "progress-after-payload",
        "pre-callable-progress",
    ] {
        assert!(
            !source.contains(token),
            "Linux x86 segmented seed は旧 progress probe token {token} を含めない"
        );
    }
}

