#[derive(Debug, Clone, PartialEq, Eq)]
struct SelfhostRegistrationDefn {
    absolute_idx: usize,
    module: String,
    file_name: String,
    decl_idx: usize,
    name: String,
}

fn escape_lsharp_string(text: &str) -> String {
    text.replace('\\', "\\\\").replace('"', "\\\"")
}

fn representative_selfhost_programs_by_module()
-> BTreeMap<String, (String, lsharp_syntax::ast::Program)> {
    let mut programs = BTreeMap::new();
    for &file_name in SELFHOST_APP_MAIN_REPRESENTATIVE_MODULES {
        let source = std::fs::read_to_string(selfhost_source_path(file_name))
            .unwrap_or_else(|err| panic!("selfhost source 読み込みに失敗 ({file_name}): {err}"));
        let program = parse_for_pipeline(&source);
        let module_name = program
            .decls
            .iter()
            .find_map(|decl| match decl {
                lsharp_syntax::ast::Decl::ModuleDecl { name, .. } => Some(name.clone()),
                _ => None,
            })
            .unwrap_or_else(|| panic!("module 宣言が見つからない: {file_name}"));
        let replaced = programs.insert(module_name.clone(), (file_name.to_string(), program));
        assert!(
            replaced.is_none(),
            "representative module が重複している: {module_name}"
        );
    }
    programs
}

fn collect_representative_selfhost_module_order(
    module_name: &str,
    programs: &BTreeMap<String, (String, lsharp_syntax::ast::Program)>,
    seen: &mut BTreeSet<String>,
    ordered_modules: &mut Vec<String>,
) {
    if !seen.insert(module_name.to_string()) {
        return;
    }
    let (_, program) = programs
        .get(module_name)
        .unwrap_or_else(|| panic!("representative module が見つからない: {module_name}"));
    for decl in &program.decls {
        if let lsharp_syntax::ast::Decl::ImportDecl { module, .. } = decl
            && programs.contains_key(module)
        {
            collect_representative_selfhost_module_order(module, programs, seen, ordered_modules);
        }
    }
    ordered_modules.push(module_name.to_string());
}

fn representative_selfhost_registration_order() -> Vec<SelfhostRegistrationDefn> {
    let programs = representative_selfhost_programs_by_module();
    let mut seen = BTreeSet::new();
    let mut ordered_modules = Vec::new();
    collect_representative_selfhost_module_order(
        "App.Main",
        &programs,
        &mut seen,
        &mut ordered_modules,
    );

    let mut absolute_idx = 10usize;
    let mut ordered_defns = Vec::new();
    for module_name in ordered_modules {
        let (file_name, program) = programs
            .get(&module_name)
            .unwrap_or_else(|| panic!("representative program が見つからない: {module_name}"));
        for (decl_idx, decl) in program.decls.iter().enumerate() {
            if let lsharp_syntax::ast::Decl::Defn { name, .. } = decl {
                ordered_defns.push(SelfhostRegistrationDefn {
                    absolute_idx,
                    module: module_name.clone(),
                    file_name: file_name.clone(),
                    decl_idx,
                    name: name.clone(),
                });
                absolute_idx += 1;
            }
        }
    }
    ordered_defns
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeHostArtifactObservation {
    program_object_hash: u64,
    runtime_object_hash: u64,
    response_text_hash: u64,
    program_binary_hash: u64,
}

/// NATIVE-05/NATIVE-06: selfhost/src/App/Main.ls の native summary が
/// direct native pipeline harness と一致すること。
#[test]
#[ignore]
fn test_e2e_selfhost_main_native_summary_matches_direct_pipeline_harness() {
    let main_output = compile_and_run_file(&selfhost_main_path());
    let main_lines = parse_numeric_lines(&main_output);
    assert!(
        main_lines.len() >= 71,
        "selfhost/src/App/Main.ls native summary 出力が不足: {:?}",
        main_lines
    );

    let direct_output = run_native_pipeline_harness(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import Backend.Native.NativeEmit)
(import Backend.Native.Linker)

(defn make-instr [opcode operand]
  (vector-push (vector-push (vector-new 2) opcode) operand))

(defn emit-summary [triple-id]
  (let [instr (make-instr 1 42)
        ir (vector-push (vector-new 1) instr)
        target (make-target triple-id)
        native (emit-native ir target)
        object (emit-object native target)
        single-objects (vector-push (vector-new 1) (vector-length object))
        single-args (build-linker-args single-objects 99 target)
        single-response (generate-response-file single-args)
        multi-objects (vector-push (vector-push (vector-new 2) (vector-length object)) (vector-length object))
        multi-args (build-linker-args multi-objects 99 target)
        multi-response (generate-response-file multi-args)]
    (do
      (print (vector-length native))
      (print (vector-length object))
      (print (link-objects single-objects 99 target))
      (print (target-arch target))
      (print (target-obj-format target))
      (print (select-linker target))
      (print (vector-length ir))
      (print (vector-get object 0))
      (print (vector-get object 4))
      (print (vector-get single-response 2))
      (print (vector-get single-response 4))
      (print (vector-get multi-response 6))
      (print (link-objects multi-objects 99 target)))))

(defn main []
  (do
    (emit-summary 1)
    (emit-summary 3)
    (emit-summary 2)
    0))"#,
    );
    let direct_lines = parse_numeric_lines(&direct_output);
    assert!(
        direct_lines.len() >= 39,
        "direct native pipeline harness 出力が不足: {:?}",
        direct_lines
    );

    let expected = parse_direct_summaries(&direct_lines);
    let actual = [
        parse_main_summary(&main_lines, NativeSummaryKind::Darwin),
        parse_main_summary(&main_lines, NativeSummaryKind::Linux),
        parse_main_summary(&main_lines, NativeSummaryKind::Aarch64),
    ];

    assert_eq!(
        actual, expected,
        "selfhost/src/App/Main.ls native summary が direct native pipeline harness と一致しない"
    );
}

