#[test]
#[ignore = "linux-x86 actual stage2 regression: entrypoint call rel32 must not escape the bundle"]
fn test_e2e_selfhost_main_representative_x86_entrypoint_first_call_stays_in_bundle() {
    let bundle = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        run_selfhost_main_native_x86_function_meta_bundle_host_bytes_harness_with_exprs(
            "native-stage23-representative-x86-entrypoint-call-range",
            r#"(compile-file-pairs-with-cache "src/App/Main.ls" cache-ref parse-count-ref)"#,
            r#"(compile-file-functions-payload-with-cache "src/App/Main.ls" 10 cache-ref parse-count-ref)"#,
        )
    });

    let entry = bundle.entrypoint_offset;
    assert!(
        entry + 16 <= bundle.code_bytes.len(),
        "entrypoint window が code 範囲外: entry={} len={}",
        entry,
        bundle.code_bytes.len()
    );
    assert_eq!(
        &bundle.code_bytes[entry..entry + 4],
        &[0x55, 0x48, 0x89, 0xe5],
        "x86 entrypoint は push rbp; mov rbp,rsp で始まるべき"
    );
    let call_offset = (entry..(entry + 128).min(bundle.code_bytes.len().saturating_sub(5)))
        .find(|offset| bundle.code_bytes[*offset] == 0xe8)
        .unwrap_or_else(|| panic!("entrypoint 近傍に rel32 call が無い: entry={entry}"));
    let rel = i32::from_le_bytes([
        bundle.code_bytes[call_offset + 1],
        bundle.code_bytes[call_offset + 2],
        bundle.code_bytes[call_offset + 3],
        bundle.code_bytes[call_offset + 4],
    ]);
    let target = call_offset as isize + 5 + rel as isize;
    assert!(
        (0..bundle.code_bytes.len() as isize).contains(&target),
        "entrypoint first call target が bundle 外: entry={} call_offset={} rel={} target={} len={}",
        entry,
        call_offset,
        rel,
        target,
        bundle.code_bytes.len()
    );
    let target_byte = bundle.code_bytes[target as usize];
    assert!(
        target_byte != 0xff,
        "entrypoint first call target が命令途中の 0xff byte に着地している: entry={} call_offset={} rel={} target={} target_window={:?}",
        entry,
        call_offset,
        rel,
        target,
        &bundle.code_bytes[target as usize..(target as usize + 16).min(bundle.code_bytes.len())]
    );
}

#[test]
fn test_native_codegen_x86_rel32_emitters_use_single_byte_vector() {
    let source = selfhost_module("NativeCodegen.ls");
    let call_body = source
        .split("(defn emit-call-rel32")
        .nth(1)
        .and_then(|tail| tail.split(";; x86_64 の JMP rel32").next())
        .expect("NativeCodegen.ls に emit-call-rel32 が存在すること");
    assert!(
        call_body.contains("(concat-byte-vectors-rooted")
            && call_body.contains("(byte-vector-1 232)")
            && call_body.contains("(encode-s32-le disp)"),
        "emit-call-rel32 は selfhost stage1 で CALL opcode と rel32 即値を rooted concat で保持するべき"
    );

    let jmp_body = source
        .split("(defn emit-jmp-rel32")
        .nth(1)
        .and_then(|tail| tail.split(";; x86_64 の TEST eax, eax").next())
        .expect("NativeCodegen.ls に emit-jmp-rel32 が存在すること");
    assert!(
        jmp_body.contains("(byte-vector-5")
            && jmp_body.contains("233")
            && !jmp_body.contains("(concat-byte-vectors-rooted"),
        "emit-jmp-rel32 は既存の単一 byte-vector-5 で構築するべき"
    );
    let vector_helper = source
        .split("(defn byte-vector-5")
        .nth(1)
        .and_then(|tail| tail.split("(defn emit-x86-rbp-disp32").next())
        .expect("NativeCodegen.ls に byte-vector-5 が存在すること");
    assert!(
        vector_helper.contains("vector-push-five-rooted"),
        "rel32 emitter 用の byte-vector-5 は rooted push helper を使うべき"
    );
}

#[test]
fn test_e2e_selfhost_minimal_x86_one_arg_call_targets_callee_not_self() {
    let source = "(module Main)\n(defn id1 [x] x)\n(defn main []\n  (id1 3))\n";
    let escaped_source = escape_lsharp_string(source);
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/MinCall.ls" "{escaped_source}")
            (compile-file-functions-payload-with-cache "src/App/MinCall.ls" 10 cache-ref parse-count-ref))"#
    );
    let bundle = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        run_selfhost_main_native_x86_segmented_host_bytes_harness_with_payload_and_args(
            "native-x86-minimal-one-arg-call-target",
            &payload_expr,
            &[],
        )
    });
    let entry = bundle.entrypoint_offset;
    let call_offset = (entry..(entry + 96).min(bundle.code_bytes.len().saturating_sub(5)))
        .find(|offset| bundle.code_bytes[*offset] == 0xe8)
        .unwrap_or_else(|| panic!("minimal one-arg entrypoint に rel32 call が無い"));
    let rel = i32::from_le_bytes([
        bundle.code_bytes[call_offset + 1],
        bundle.code_bytes[call_offset + 2],
        bundle.code_bytes[call_offset + 3],
        bundle.code_bytes[call_offset + 4],
    ]);
    let target = call_offset as isize + 5 + rel as isize;

    assert!(
        target >= 0 && (target as usize) < entry,
        "minimal one-arg call は entrypoint 自身ではなく前方の callee を指すべき: entry={entry} call_offset={call_offset} rel={rel} target={target}"
    );
}

#[test]
fn test_e2e_selfhost_minimal_x86_zero_arg_call_preserves_depth_zero_call_bytes() {
    let source = "(module Main)\n(defn z [] 5)\n(defn main []\n  (z))\n";
    let escaped_source = escape_lsharp_string(source);
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/MinZeroDepth0Call.ls" "{escaped_source}")
            (compile-file-functions-payload-with-cache "src/App/MinZeroDepth0Call.ls" 10 cache-ref parse-count-ref))"#
    );
    let bundle = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        run_selfhost_main_native_x86_segmented_host_bytes_harness_with_payload_and_args(
            "native-x86-minimal-zero-arg-depth0-call-bytes",
            &payload_expr,
            &[],
        )
    });
    let entry = bundle.entrypoint_offset;
    let end = (entry + 96).min(bundle.code_bytes.len().saturating_sub(5));
    let call_offset = (entry..end)
        .find(|offset| bundle.code_bytes[*offset] == 0xe8)
        .unwrap_or_else(|| {
            panic!(
                "depth=0 zero-arg call should emit bare call rel32, entry={entry}, bytes={:?}",
                &bundle.code_bytes[entry..end]
            )
        });

    assert_ne!(
        &bundle.code_bytes[call_offset..call_offset + 5],
        &[0, 0, 0, 0, 0],
        "stage1-generated stage2 depth=0 zero-arg call bytes must not be zero-filled"
    );
    let rel = i32::from_le_bytes([
        bundle.code_bytes[call_offset + 1],
        bundle.code_bytes[call_offset + 2],
        bundle.code_bytes[call_offset + 3],
        bundle.code_bytes[call_offset + 4],
    ]);
    let target = call_offset as isize + 5 + rel as isize;
    assert!(
        target >= 0 && (target as usize) < entry,
        "depth=0 zero-arg call は entrypoint 自身ではなく前方の callee を指すべき: entry={entry} call_offset={call_offset} rel={rel} target={target}"
    );
}

#[test]
fn test_e2e_selfhost_minimal_x86_zero_arg_call_preserves_call_bytes_after_value() {
    let source = "(module Main)\n(defn z [] 5)\n(defn main []\n  (+ 7 (z)))\n";
    let escaped_source = escape_lsharp_string(source);
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/MinZeroCall.ls" "{escaped_source}")
            (compile-file-functions-payload-with-cache "src/App/MinZeroCall.ls" 10 cache-ref parse-count-ref))"#
    );
    let bundle = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        run_selfhost_main_native_x86_segmented_host_bytes_harness_with_payload_and_args(
            "native-x86-minimal-zero-arg-call-bytes",
            &payload_expr,
            &[],
        )
    });
    let entry = bundle.entrypoint_offset;
    let end = (entry + 128).min(bundle.code_bytes.len().saturating_sub(7));
    let call_offset = (entry..end)
        .find(|offset| {
            bundle.code_bytes[*offset] == 0x50
                && bundle.code_bytes[*offset + 1] == 0xe8
                && bundle.code_bytes[*offset + 6] == 0x59
        })
        .unwrap_or_else(|| {
            panic!(
                "zero-arg call after live value should emit push/call/pop, entry={entry}, bytes={:?}",
                &bundle.code_bytes[entry..end]
            )
        });

    assert_ne!(
        &bundle.code_bytes[call_offset..call_offset + 7],
        &[0, 0, 0, 0, 0, 0, 0],
        "stage1-generated stage2 zero-arg call bundle must not be zero-filled"
    );
}

#[test]
fn test_e2e_selfhost_minimal_main_ir_call_operand_points_to_id1() {
    let source = "(module Main)\n(defn id1 [x] x)\n(defn main []\n  (id1 3))\n";
    let escaped_source = escape_lsharp_string(source);
    let harness = format!(
        r#"(module App.HarnessMain)
(import App.CompilerMode)
(import Backend.Wasm.CompilerBase)

(defn first-call-operand [ir idx len]
  (if (>= idx len)
    -1
    (let [instr (vector-get ir idx)]
      (if (= (vector-get instr 0) 40)
        (vector-get instr 1)
        (first-call-operand ir (+ idx 1) len)))))

(defn main []
  (do
    (write-file "src/App/MinCall.ls" "{escaped_source}")
    (let [cache-ref (ref-new (map-new))
          parse-count-ref (ref-new 0)
          payload (compile-file-functions-payload-with-cache "src/App/MinCall.ls" 10 cache-ref parse-count-ref)
          functions (vector-get payload 0)
          main-func (vector-get functions 1)
          ir (function-meta-ir main-func)]
      (print (first-call-operand ir 0 (vector-length ir))))))"#
    );
    let output = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        try_compile_and_run_selfhost_fixture_entry_with_dir_and_args(
            "selfhost-minimal-main-ir-call-operand",
            SELFHOST_APP_MAIN_REPRESENTATIVE_MODULES,
            "src/App/HarnessMain.ls",
            &harness,
            &[],
        )
    })
    .expect("minimal main IR call operand probe 実行に失敗");
    let lines = parse_numeric_lines(&output);
    assert_eq!(
        lines,
        vec![10],
        "minimal main の `(id1 3)` は id1 の absolute func idx 10 を call operand に持つべき"
    );
}

#[allow(dead_code)]
fn run_selfhost_main_override_native_function_meta_code_only_host_bytes_harness(
    label: &str,
    main_source: &str,
) -> (usize, Vec<u8>, usize, Vec<u8>) {
    let escaped_main_source = escape_lsharp_string(main_source);
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/OverrideMain.ls" "{escaped_main_source}")
            (compile-file-functions-payload-with-cache "src/App/OverrideMain.ls" 10 cache-ref parse-count-ref))"#
    );
    run_selfhost_main_native_function_meta_code_only_host_bytes_harness_with_payload(
        label,
        &payload_expr,
    )
}

fn parse_transport_ascii_line<'a>(line: Option<&'a [u8]>, missing_message: &str) -> &'a str {
    let bytes = line.unwrap_or_else(|| panic!("{missing_message}"));
    std::str::from_utf8(bytes)
        .unwrap_or_else(|_| panic!("transport prefix が UTF-8 でない: {missing_message}"))
}

fn is_transport_separator(byte: u8) -> bool {
    byte == 0 || byte.is_ascii_control() || !byte.is_ascii()
}

#[test]
fn test_extract_transport_lines_skips_non_utf8_prefix() {
    let output = [
        0xff, 0x00, b'X', b'\n', b'9', b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'1', b'\n',
        b'1', b'2', b'\n', b'9', b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'2', b'\n', b'A',
        b'B', b'C', b'D',
    ];
    let (sentinel_start, declared_len, sentinel_end, payload) =
        extract_transport_lines(&output, "transport test");
    assert_eq!(sentinel_start, "9000000001");
    assert_eq!(declared_len, "12");
    assert_eq!(sentinel_end, "9000000002");
    assert_eq!(payload, b"ABCD");
}

#[test]
fn test_extract_transport_lines_supports_0xf9_separators() {
    let output = [
        b'9', b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'1', 0xf9, b'1', b'2', 0xf9, b'9',
        b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'0', b'2', 0xf9, b'A', b'B',
    ];
    let (sentinel_start, declared_len, sentinel_end, payload) =
        extract_transport_lines(&output, "transport test");
    assert_eq!(sentinel_start, "9000000001");
    assert_eq!(declared_len, "12");
    assert_eq!(sentinel_end, "9000000002");
    assert_eq!(payload, b"AB");
}

#[test]
fn test_extract_transport_lines_supports_non_ascii_separators() {
    let output = b"9000000001\xe112\xe19000000002\xe1AB";
    let (sentinel_start, declared_len, sentinel_end, payload) =
        extract_transport_lines(output, "transport test");
    assert_eq!(sentinel_start, "9000000001");
    assert_eq!(declared_len, "12");
    assert_eq!(sentinel_end, "9000000002");
    assert_eq!(payload, b"AB");
}

#[test]
fn test_decode_packed_byte_lines_supports_nul_separators() {
    let decoded = decode_packed_byte_lines(b"513\x00784\0", 4);
    assert_eq!(decoded, vec![1, 2, 16, 3]);
}

#[test]
fn test_decode_packed_byte_lines_supports_negative_i16_text() {
    let decoded = decode_packed_byte_lines(b"-255\0", 2);
    assert_eq!(decoded, vec![1, 255]);
}

#[test]
fn test_decode_packed_byte_lines_width_supports_negative_i64_text() {
    let decoded = decode_packed_byte_lines_with_width(b"-1\n", 8, 8);
    assert_eq!(decoded, vec![255; 8]);
}

#[test]
fn test_extract_native_code_data_transport_output_supports_packed_payloads() {
    let output = b"9000000001\n4\n9000000002\n513\n784\n9000000003\n3\n9000000004\n2055\n9\n";
    let (declared_code_len, code_bytes, declared_data_len, data_bytes) =
        extract_native_code_data_transport_output(output, "packed transport test");
    assert_eq!(declared_code_len, 4);
    assert_eq!(code_bytes, vec![1, 2, 16, 3]);
    assert_eq!(declared_data_len, 3);
    assert_eq!(data_bytes, vec![7, 8, 9]);
}

#[test]
fn test_extract_native_code_data_transport_output_supports_segmented_packed_payloads() {
    let output = b"9000000001\n5\n9000000002\n9000000010\n2\n513\n9000000010\n3\n197121\n9000000003\n0\n9000000004\n";
    let (declared_code_len, code_bytes, declared_data_len, data_bytes) =
        extract_native_code_data_transport_output(output, "segmented packed transport test");
    assert_eq!(declared_code_len, 5);
    assert_eq!(code_bytes, vec![1, 2, 1, 2, 3]);
    assert_eq!(declared_data_len, 0);
    assert!(data_bytes.is_empty());
}

#[test]
fn test_extract_native_code_data_transport_output_reads_optional_layout() {
    let output =
        b"9000000005\n12\n11\n128\n9000000006\n9000000001\n1\n9000000002\n42\n9000000003\n0\n9000000004\n";
    let transport = extract_native_code_data_transport_output_with_optional_layout(
        output,
        "layout transport test",
    );
    let layout = transport
        .layout
        .expect("layout transport が layout を復元できない");
    assert_eq!(layout.function_start_len, 12);
    assert_eq!(layout.main_func_idx, 11);
    assert_eq!(layout.entrypoint_offset, 128);
    assert_eq!(transport.code_bytes, vec![42]);
    assert!(transport.data_bytes.is_empty());
}

fn next_transport_line(output: &[u8], start: usize) -> Option<(&[u8], usize)> {
    if start > output.len() {
        return None;
    }
    let tail = &output[start..];
    if let Some(end) = tail.iter().position(|byte| is_transport_separator(*byte)) {
        Some((&tail[..end], start + end + 1))
    } else {
        Some((tail, output.len()))
    }
}

fn extract_transport_start<'a>(output: &'a [u8], context: &str) -> (&'a str, usize) {
    let missing_start = || {
        panic!(
            "{context} start sentinel が無い: output_len={} first_bytes={:?}",
            output.len(),
            &output[..output.len().min(32)]
        )
    };
    let mut offset = 0;
    loop {
        let (line, next_offset) = next_transport_line(output, offset).unwrap_or_else(missing_start);
        offset = next_offset;
        if let Ok(text) = std::str::from_utf8(line)
            && text == "9000000001"
        {
            return (text, offset);
        }
        if offset >= output.len() {
            missing_start();
        }
    }
}

fn extract_transport_lines<'a>(
    output: &'a [u8],
    context: &str,
) -> (&'a str, &'a str, &'a str, &'a [u8]) {
    let (sentinel_start, offset) = extract_transport_start(output, context);
    let (declared_code_len_line, after_declared_len) = next_transport_line(output, offset)
        .unwrap_or_else(|| panic!("{context} code len 出力が不足"));
    let declared_code_len = parse_transport_ascii_line(
        Some(declared_code_len_line),
        &format!("{context} code len 出力が不足"),
    );
    let (sentinel_end_line, payload_offset) = next_transport_line(output, after_declared_len)
        .unwrap_or_else(|| panic!("{context} end sentinel が無い"));
    let sentinel_end = parse_transport_ascii_line(
        Some(sentinel_end_line),
        &format!("{context} end sentinel が無い"),
    );
    (
        sentinel_start,
        declared_code_len,
        sentinel_end,
        &output[payload_offset..],
    )
}

fn decode_packed_byte_lines(payload: &[u8], declared_code_len: usize) -> Vec<u8> {
    decode_packed_byte_lines_with_width(payload, declared_code_len, 2)
}

fn decode_packed_byte_lines_with_width(
    payload: &[u8],
    declared_code_len: usize,
    bytes_per_line: usize,
) -> Vec<u8> {
    let mut decoded = Vec::with_capacity(declared_code_len);
    for (idx, line) in payload
        .split(|byte| is_transport_separator(*byte))
        .filter(|line| !line.is_empty())
        .enumerate()
    {
        let line_text = std::str::from_utf8(line)
            .unwrap_or_else(|_| panic!("packed byte line が UTF-8 でない: {:?}", line));
        let packed = line_text
            .parse::<i64>()
            .unwrap_or_else(|_| panic!("packed byte line parse 失敗 at {idx}: {line_text}"))
            as u64;
        for byte_idx in 0..bytes_per_line {
            if decoded.len() >= declared_code_len {
                break;
            }
            decoded.push(((packed >> (byte_idx * 8)) & 0x00ff) as u8);
        }
        if decoded.len() >= declared_code_len {
            break;
        }
    }
    assert_eq!(
        decoded.len(),
        declared_code_len,
        "packed byte payload の復元長が一致しない: declared_len={} decoded_len={}",
        declared_code_len,
        decoded.len()
    );
    decoded
}

fn decode_printed_byte_values(payload: &[u8], declared_code_len: usize) -> Vec<u8> {
    let decoded = payload
        .split(|byte| is_transport_separator(*byte))
        .filter(|line| !line.is_empty())
        .enumerate()
        .map(|(idx, line)| {
            let line_text = std::str::from_utf8(line)
                .unwrap_or_else(|_| panic!("printed byte line が UTF-8 でない: {:?}", line));
            let value = line_text
                .parse::<i32>()
                .unwrap_or_else(|_| panic!("printed byte line parse 失敗 at {idx}: {line_text}"));
            u8::try_from(value)
                .unwrap_or_else(|_| panic!("printed byte line が 0..255 でない at {idx}: {value}"))
        })
        .collect::<Vec<_>>();
    assert_eq!(
        decoded.len(),
        declared_code_len,
        "printed byte payload の復元長が一致しない: declared_len={} decoded_len={}",
        declared_code_len,
        decoded.len()
    );
    decoded
}

fn decode_numeric_transport_payload(payload: &[u8], declared_code_len: usize) -> Vec<u8> {
    let lines = payload
        .split(|byte| is_transport_separator(*byte))
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>();
    if lines.first().copied() == Some(b"9000000010".as_slice()) {
        return decode_segmented_packed_transport_payload(&lines, declared_code_len);
    }
    let line_count = payload
        .split(|byte| is_transport_separator(*byte))
        .filter(|line| !line.is_empty())
        .count();
    if line_count == declared_code_len {
        decode_printed_byte_values(payload, declared_code_len)
    } else if line_count == declared_code_len.div_ceil(8) {
        decode_packed_byte_lines_with_width(payload, declared_code_len, 8)
    } else if line_count == declared_code_len.div_ceil(2) {
        decode_packed_byte_lines(payload, declared_code_len)
    } else {
        decode_transport_payload(payload, declared_code_len)
    }
}

fn decode_segmented_packed_transport_payload(lines: &[&[u8]], declared_code_len: usize) -> Vec<u8> {
    let mut decoded = Vec::with_capacity(declared_code_len);
    let mut idx = 0;
    while idx < lines.len() {
        let marker = std::str::from_utf8(lines[idx]).unwrap_or_else(|_| {
            panic!("segmented packed marker が UTF-8 でない: {:?}", lines[idx])
        });
        assert_eq!(
            marker, "9000000010",
            "segmented packed marker が期待値と一致しない at {idx}: {marker}"
        );
        idx += 1;
        let len_text = std::str::from_utf8(
            lines
                .get(idx)
                .copied()
                .unwrap_or_else(|| panic!("segmented packed length が不足 at {idx}")),
        )
        .unwrap_or_else(|_| panic!("segmented packed length が UTF-8 でない at {idx}"));
        let segment_len = len_text
            .parse::<usize>()
            .unwrap_or_else(|_| panic!("segmented packed length parse 失敗 at {idx}: {len_text}"));
        idx += 1;
        let packed_len = segment_len.div_ceil(8);
        let end = idx + packed_len;
        assert!(
            end <= lines.len(),
            "segmented packed payload が不足: segment_len={segment_len} idx={idx} lines={}",
            lines.len()
        );
        let mut segment_payload = Vec::new();
        for line in &lines[idx..end] {
            if !segment_payload.is_empty() {
                segment_payload.push(b'\n');
            }
            segment_payload.extend_from_slice(line);
        }
        decoded.extend(decode_packed_byte_lines_with_width(
            &segment_payload,
            segment_len,
            8,
        ));
        idx = end;
    }
    assert_eq!(
        decoded.len(),
        declared_code_len,
        "segmented packed payload の復元長が一致しない: declared_len={} decoded_len={}",
        declared_code_len,
        decoded.len()
    );
    decoded
}

fn decode_base64_value(byte: u8) -> Option<u8> {
    match byte {
        b'A'..=b'Z' => Some(byte - b'A'),
        b'a'..=b'z' => Some(byte - b'a' + 26),
        b'0'..=b'9' => Some(byte - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

fn strip_chunk_separators(
    payload: &[u8],
    declared_code_len: usize,
    encoded_chunk_len: impl Fn(usize) -> usize,
) -> Option<Vec<u8>> {
    if declared_code_len == 0 {
        return payload.is_empty().then(Vec::new);
    }

    let mut stripped = Vec::new();
    let mut payload_idx = 0;
    let mut code_idx = 0;
    while code_idx < declared_code_len {
        let chunk_len = (declared_code_len - code_idx).min(768);
        let symbol_len = encoded_chunk_len(chunk_len);
        let end = payload_idx + symbol_len;
        if end >= payload.len() {
            return None;
        }
        stripped.extend_from_slice(&payload[payload_idx..end]);
        payload_idx = end + 1;
        code_idx += chunk_len;
    }
    (payload_idx == payload.len()).then_some(stripped)
}

fn decode_mixed_base64_value(byte: u8) -> Option<u8> {
    decode_base64_value(byte).or_else(|| (byte <= 63).then_some(byte))
}

fn decode_mixed_base64_symbols(symbols: &[u8], declared_code_len: usize) -> Vec<u8> {
    assert!(
        symbols.len().is_multiple_of(4),
        "base64 payload length が 4 の倍数でない: {}",
        symbols.len()
    );

    let mut decoded = Vec::with_capacity((symbols.len() / 4) * 3);
    for chunk in symbols.chunks_exact(4) {
        let a = decode_mixed_base64_value(chunk[0])
            .unwrap_or_else(|| panic!("base64 decode 失敗: {}", chunk[0]));
        let b = decode_mixed_base64_value(chunk[1])
            .unwrap_or_else(|| panic!("base64 decode 失敗: {}", chunk[1]));
        let c = decode_mixed_base64_value(chunk[2])
            .unwrap_or_else(|| panic!("base64 decode 失敗: {}", chunk[2]));
        let d = decode_mixed_base64_value(chunk[3])
            .unwrap_or_else(|| panic!("base64 decode 失敗: {}", chunk[3]));
        decoded.push((a << 2) | (b >> 4));
        decoded.push(((b & 0x0f) << 4) | (c >> 2));
        decoded.push(((c & 0x03) << 6) | d);
    }
    decoded.truncate(declared_code_len);
    decoded
}

#[test]
fn test_decode_mixed_base64_value_prefers_ascii_alphabet_over_raw_sextet() {
    assert_eq!(decode_mixed_base64_value(b'0'), Some(52));
    assert_eq!(decode_mixed_base64_value(b'9'), Some(61));
    assert_eq!(decode_mixed_base64_value(b'+'), Some(62));
    assert_eq!(decode_mixed_base64_value(b'/'), Some(63));
    assert_eq!(decode_mixed_base64_value(17), Some(17));
}

fn decode_transport_payload(payload: &[u8], declared_code_len: usize) -> Vec<u8> {
    if payload.len() == declared_code_len {
        return payload.to_vec();
    }
    if let Some(raw_bytes) =
        strip_chunk_separators(payload, declared_code_len, |chunk_len| chunk_len)
    {
        return raw_bytes;
    }

    let encoded_symbol_len = |chunk_len: usize| chunk_len.div_ceil(3) * 4;
    let encoded_total_len = encoded_symbol_len(declared_code_len);
    if payload.len() == encoded_total_len {
        if payload
            .iter()
            .all(|byte| decode_mixed_base64_value(*byte).is_some())
        {
            return decode_mixed_base64_symbols(payload, declared_code_len);
        }
        let first_non_decodable = payload
            .iter()
            .copied()
            .find(|byte| decode_mixed_base64_value(*byte).is_none())
            .unwrap_or_default();
        let invalid_positions = payload
            .iter()
            .enumerate()
            .filter_map(|(idx, byte)| {
                decode_mixed_base64_value(*byte)
                    .is_none()
                    .then_some((idx, *byte))
            })
            .take(12)
            .collect::<Vec<_>>();
        let invalid_windows = invalid_positions
            .iter()
            .map(|(idx, _)| {
                let start = idx.saturating_sub(4);
                let end = (*idx + 5).min(payload.len());
                (*idx, payload[start..end].to_vec())
            })
            .collect::<Vec<_>>();
        let invalid_count = payload
            .iter()
            .filter(|byte| decode_mixed_base64_value(**byte).is_none())
            .count();
        let max_byte = payload.iter().copied().max().unwrap_or_default();
        panic!(
            "transport payload encoded symbols が decode できない: payload_len={}, declared_code_len={}, first_bytes={:?}, first_non_decodable={}, max_byte={}, invalid_count={}, invalid_positions={:?}, invalid_windows={:?}",
            payload.len(),
            declared_code_len,
            &payload[..payload.len().min(16)],
            first_non_decodable,
            max_byte,
            invalid_count,
            invalid_positions,
            invalid_windows
        );
    }
    if let Some(symbols) = strip_chunk_separators(payload, declared_code_len, encoded_symbol_len) {
        if symbols
            .iter()
            .all(|byte| decode_mixed_base64_value(*byte).is_some())
        {
            return decode_mixed_base64_symbols(&symbols, declared_code_len);
        }
        let first_non_decodable = symbols
            .iter()
            .copied()
            .find(|byte| decode_mixed_base64_value(*byte).is_none())
            .unwrap_or_default();
        let max_byte = symbols.iter().copied().max().unwrap_or_default();
        panic!(
            "transport payload の形式が不明: payload_len={}, declared_code_len={}, first_bytes={:?}, first_non_decodable={}, max_byte={}",
            payload.len(),
            declared_code_len,
            &symbols[..symbols.len().min(16)],
            first_non_decodable,
            max_byte
        );
    }

    panic!(
        "transport payload 長を解釈できない: payload_len={}, declared_code_len={}",
        payload.len(),
        declared_code_len
    );
}

