fn host_target_deep_direct_call_arg_drop_restore_code_bytes(depth: usize) -> Vec<u8> {
    assert!(
        depth >= 2,
        "deep direct call drop restore は底値 + call 前 value を含む深さが必要"
    );
    let mut caller_instrs = Vec::with_capacity(depth + 2);
    for idx in 0..depth {
        let value = if idx == 0 { 7 } else { 40 + idx as u32 };
        caller_instrs.push(format!("(make-i64-const {value})"));
    }
    caller_instrs.push("(make-call 1)".to_string());
    for _ in 0..depth {
        caller_instrs.push("(make-instr 44 0)".to_string());
    }

    let caller_bindings = caller_instrs
        .iter()
        .enumerate()
        .map(|(idx, expr)| format!("caller-instr{idx} {expr}"))
        .collect::<Vec<_>>()
        .join("\n        ");
    let caller_ir_expr = (0..caller_instrs.len()).fold(
        format!("(vector-new {})", caller_instrs.len()),
        |expr, idx| format!("(vector-push {expr} caller-instr{idx})"),
    );
    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn print-bytes [bytes idx n]
  (if (>= idx n)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) n))))

(defn main []
  (let [{caller_bindings}
        caller-ir {caller_ir_expr}
        callee-ir (vector-push (vector-new 1) (make-local-get 0))
        caller (make-function-meta 0 0 caller-ir)
        callee (make-function-meta 1 0 callee-ir)
        functions (vector-push (vector-push (vector-new 2) caller) callee)
        target (host-target)
        code (emit-native-function-meta-bundle functions target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
    );
    run_native_codegen_host_bytes_harness(&source)
}

fn host_target_deep_command_line_arg_string_length_drop_restore_code_bytes(
    depth: usize,
    arg_index: u32,
) -> Vec<u8> {
    assert!(
        depth >= 2,
        "deep command-line-arg/string-length drop restore は底値 + helper 前 value を含む深さが必要"
    );
    let mut instrs = Vec::with_capacity(depth + 3);
    for idx in 0..depth {
        let value = if idx == 0 { 7 } else { 40 + idx as u32 };
        instrs.push(format!("(make-instr 3 {value})"));
    }
    instrs.push(format!("(make-instr 3 {arg_index})"));
    instrs.push("(make-instr 67 0)".to_string());
    instrs.push("(make-instr 51 0)".to_string());
    for _ in 0..depth {
        instrs.push("(make-instr 44 0)".to_string());
    }

    let bindings = instrs
        .iter()
        .enumerate()
        .map(|(idx, expr)| format!("instr{idx} {expr}"))
        .collect::<Vec<_>>()
        .join("\n        ");
    let ir_expr = (0..instrs.len()).fold(format!("(vector-new {})", instrs.len()), |expr, idx| {
        format!("(vector-push {expr} instr{idx})")
    });
    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn print-bytes [bytes idx n]
  (if (>= idx n)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) n))))

(defn main []
  (let [{bindings}
        ir {ir_expr}
        func (make-function-meta 0 0 ir)
        functions (vector-push (vector-new 1) func)
        target (host-target)
        code (emit-native-function-meta-bundle functions target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
    );
    run_native_codegen_host_bytes_harness(&source)
}

fn host_target_deep_command_line_arg_substring_length_code_bytes(
    depth: usize,
    arg_index: u32,
    start: u32,
    end: u32,
) -> Vec<u8> {
    assert!(
        depth >= 3,
        "deep command-line-arg substring は filler を含む深さが必要"
    );
    let mut instrs = Vec::with_capacity(depth + 10);
    for idx in 0..depth {
        let value = if idx == 0 { 7 } else { 40 + idx as u32 };
        instrs.push(format!("(make-instr 3 {value})"));
    }
    instrs.push(format!("(make-instr 3 {arg_index})"));
    instrs.push("(make-instr 67 0)".to_string());
    instrs.push("(make-instr 11 0)".to_string());
    instrs.push("(make-instr 10 0)".to_string());
    instrs.push("(make-instr 74 0)".to_string());
    instrs.push("(make-instr 44 0)".to_string());
    instrs.push("(make-instr 10 0)".to_string());
    instrs.push(format!("(make-instr 3 {start})"));
    instrs.push(format!("(make-instr 3 {end})"));
    instrs.push("(make-instr 69 0)".to_string());
    instrs.push("(make-instr 75 0)".to_string());
    instrs.push("(make-instr 44 0)".to_string());
    instrs.push("(make-instr 51 0)".to_string());

    let bindings = instrs
        .iter()
        .enumerate()
        .map(|(idx, expr)| format!("instr{idx} {expr}"))
        .collect::<Vec<_>>()
        .join("\n        ");
    let ir_expr = (0..instrs.len()).fold(format!("(vector-new {})", instrs.len()), |expr, idx| {
        format!("(vector-push {expr} instr{idx})")
    });
    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn print-bytes [bytes idx n]
  (if (>= idx n)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) n))))

(defn main []
  (let [{bindings}
        ir {ir_expr}
        func (make-function-meta 0 1 ir)
        functions (vector-push (vector-new 1) func)
        target (host-target)
        code (emit-native-function-meta-bundle functions target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
    );
    run_native_codegen_host_bytes_harness(&source)
}

fn host_target_deep_command_line_arg_plain_substring_length_code_bytes(
    depth: usize,
    arg_index: u32,
    start: u32,
    end: u32,
) -> Vec<u8> {
    assert!(
        depth >= 3,
        "deep plain command-line-arg substring は filler を含む深さが必要"
    );
    let mut instrs = Vec::with_capacity(depth + 5);
    for idx in 0..depth {
        let value = if idx == 0 { 7 } else { 40 + idx as u32 };
        instrs.push(format!("(make-instr 3 {value})"));
    }
    instrs.push(format!("(make-instr 3 {arg_index})"));
    instrs.push("(make-instr 67 0)".to_string());
    instrs.push(format!("(make-instr 3 {start})"));
    instrs.push(format!("(make-instr 3 {end})"));
    instrs.push("(make-instr 69 0)".to_string());
    instrs.push("(make-instr 51 0)".to_string());

    let bindings = instrs
        .iter()
        .enumerate()
        .map(|(idx, expr)| format!("instr{idx} {expr}"))
        .collect::<Vec<_>>()
        .join("\n        ");
    let ir_expr = (0..instrs.len()).fold(format!("(vector-new {})", instrs.len()), |expr, idx| {
        format!("(vector-push {expr} instr{idx})")
    });
    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn print-bytes [bytes idx n]
  (if (>= idx n)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) n))))

(defn main []
  (let [{bindings}
        ir {ir_expr}
        func (make-function-meta 0 0 ir)
        functions (vector-push (vector-new 1) func)
        target (host-target)
        code (emit-native-function-meta-bundle functions target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
    );
    run_native_codegen_host_bytes_harness(&source)
}

/// ネイティブバイト列を `.s` アセンブリシムでラップし、
/// clang (arm64) でリンクして実行する。戻り値は exit code。
fn link_and_run_native_host_binary(code: &[u8]) -> Result<i32, String> {
    link_and_run_native_host_binary_with_args(code, &[])
}

fn link_and_run_linux_x86_native_binary(code: &[u8]) -> Result<i32, String> {
    if !linux_x86_native_exec_supported() {
        return Err("Linux x86_64 native execution は Linux x86_64 でのみサポート".to_string());
    }

    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir("e2e-native-fixtures", "native-linux-x86-exec", id);
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        let byte_strs: Vec<String> = code.iter().map(|b| format!("0x{b:02x}")).collect();
        let asm_content = format!(
            ".text\n\
             .globl generated\n\
             generated:\n\
                 .byte {}\n\
             .globl main\n\
             main:\n\
                 push %rbp\n\
                 mov %rsp, %rbp\n\
                 call generated\n\
                 pop %rbp\n\
                 ret\n\
             .section .note.GNU-stack,\"\",@progbits\n",
            byte_strs.join(", ")
        );
        std::fs::write(dir.join("prog.s"), &asm_content)
            .map_err(|e| format!("prog.s 書き込み失敗: {e}"))?;

        let link_result = std::process::Command::new("cc")
            .args(["prog.s", "-o", "prog"])
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("cc 実行失敗: {e}"))?;

        if !link_result.status.success() {
            return Err(format!(
                "Linux x86_64 link 失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&link_result.stdout),
                String::from_utf8_lossy(&link_result.stderr),
            ));
        }

        let run_result = std::process::Command::new(dir.join("prog"))
            .output()
            .map_err(|e| format!("実行失敗: {e}"))?;

        Ok(run_result.status.code().unwrap_or(-1))
    })();

    let _ = std::fs::remove_dir_all(&dir);
    result
}

fn link_and_run_linux_x86_native_binary_via_lima(code: &[u8]) -> Result<i32, String> {
    let vm_name = std::env::var("LSHARP_NATIVE_LINUX_X86_LIMA_VM")
        .unwrap_or_else(|_| "lsharp-linux-x86".to_string());
    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir("e2e-native-fixtures", "native-linux-x86-lima-exec", id);
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let byte_strs: Vec<String> = code.iter().map(|b| format!("0x{b:02x}")).collect();
    let asm_content = format!(
        ".text\n\
         .globl generated\n\
         generated:\n\
             .byte {}\n\
         .globl main\n\
         main:\n\
             push %rbp\n\
             mov %rsp, %rbp\n\
             call generated\n\
             pop %rbp\n\
             ret\n\
         .section .note.GNU-stack,\"\",@progbits\n",
        byte_strs.join(", ")
    );
    let host_asm = dir.join("prog.s");
    std::fs::write(&host_asm, &asm_content).map_err(|e| format!("prog.s 書き込み失敗: {e}"))?;

    let vm_work_dir = format!("/tmp/lsharp-linux-x86-e2e-{id}");
    let setup = std::process::Command::new("limactl")
        .args([
            "shell",
            &vm_name,
            "--",
            "bash",
            "-lc",
            &format!("rm -rf {vm_work_dir} && mkdir -p {vm_work_dir}"),
        ])
        .output()
        .map_err(|e| format!("limactl setup 実行失敗: {e}"))?;
    if !setup.status.success() {
        return Err(format!(
            "limactl setup 失敗: stdout={:?} stderr={:?}",
            String::from_utf8_lossy(&setup.stdout),
            String::from_utf8_lossy(&setup.stderr)
        ));
    }

    let vm_asm = format!("{vm_name}:{vm_work_dir}/prog.s");
    let copy = std::process::Command::new("limactl")
        .arg("copy")
        .arg(&host_asm)
        .arg(&vm_asm)
        .output()
        .map_err(|e| format!("limactl copy 実行失敗: {e}"))?;
    if !copy.status.success() {
        return Err(format!(
            "limactl copy 失敗: stdout={:?} stderr={:?}",
            String::from_utf8_lossy(&copy.stdout),
            String::from_utf8_lossy(&copy.stderr)
        ));
    }

    let script = format!(
        "set -euo pipefail\n\
         cd {vm_work_dir}\n\
         cc prog.s -o prog\n\
         set +e\n\
         ./prog >stdout.txt 2>stderr.txt\n\
         code=$?\n\
         cat stdout.txt\n\
         cat stderr.txt >&2\n\
         exit $code\n"
    );
    let output = std::process::Command::new("limactl")
        .args(["shell", &vm_name, "--", "bash", "-lc", &script])
        .output()
        .map_err(|e| format!("limactl link/run 実行失敗: {e}"))?;
    let _ = std::process::Command::new("limactl")
        .args(["shell", &vm_name, "--", "rm", "-rf", &vm_work_dir])
        .output();

    Ok(output.status.code().unwrap_or(-1))
}

fn link_and_run_linux_x86_generated_object(program_object: &[u8]) -> Result<i32, String> {
    if !linux_x86_native_exec_supported() {
        return Err("Linux x86_64 native execution は Linux x86_64 でのみサポート".to_string());
    }

    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir("e2e-native-fixtures", "native-linux-x86-object-exec", id);
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        std::fs::write(dir.join("program.o"), program_object)
            .map_err(|e| format!("program.o 書き込み失敗: {e}"))?;
        std::fs::write(
            dir.join("runtime.s"),
            ".text\n\
             .extern generated\n\
             .globl main\n\
             main:\n\
                 call generated\n\
                 ret\n\
             .section .note.GNU-stack,\"\",@progbits\n",
        )
        .map_err(|e| format!("runtime.s 書き込み失敗: {e}"))?;

        let runtime_result = std::process::Command::new("cc")
            .args(["-c", "runtime.s", "-o", "runtime.o"])
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("runtime.o 生成失敗: {e}"))?;
        if !runtime_result.status.success() {
            return Err(format!(
                "runtime.o 生成失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&runtime_result.stdout),
                String::from_utf8_lossy(&runtime_result.stderr),
            ));
        }

        let response_text = "-o\nprogram.native\nprogram.o\nruntime.o\n";
        std::fs::write(dir.join("linker-response.txt"), response_text)
            .map_err(|e| format!("linker-response.txt 書き込み失敗: {e}"))?;
        let link_result = std::process::Command::new("cc")
            .arg("@linker-response.txt")
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("cc 実行失敗: {e}"))?;
        if !link_result.status.success() {
            return Err(format!(
                "Linux x86_64 object link 失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&link_result.stdout),
                String::from_utf8_lossy(&link_result.stderr),
            ));
        }

        let run_result = std::process::Command::new(dir.join("program.native"))
            .output()
            .map_err(|e| format!("program.native 実行失敗: {e}"))?;

        Ok(run_result.status.code().unwrap_or(-1))
    })();

    let _ = std::fs::remove_dir_all(&dir);
    result
}

fn link_and_run_native_host_binary_with_args(code: &[u8], args: &[&str]) -> Result<i32, String> {
    Ok(link_and_run_native_host_binary_capture_with_args(code, args)?.exit_code)
}

fn link_and_run_native_host_binary_capture_with_args(
    code: &[u8],
    args: &[&str],
) -> Result<NativeHostExecutionResult, String> {
    if !host_native_exec_supported() {
        return Err("host native execution は macOS arm64 でのみサポート".to_string());
    }

    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir("e2e-native-fixtures", "native-host-exec", id);
    let keep_dir = std::env::var_os("LSHARP_NATIVE_PROXY_KEEP_FAILED_DIR").is_some();
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        // バイト列を _main シンボルのアセンブリ .byte ディレクティブとして書き出す
        let byte_strs: Vec<String> = code.iter().map(|b| format!("0x{b:02x}")).collect();
        let asm_content = format!(
            ".section __TEXT,__text\n\
             .globl _generated\n\
             _generated:\n\
                  .byte {}\n\
             .globl _main\n\
             _main:\n\
                 stp x29, x30, [sp, #-80]!\n\
                 mov x29, sp\n\
                 stp x19, x20, [sp, #16]\n\
                 stp x21, x22, [sp, #32]\n\
                 stp x27, x28, [sp, #48]\n\
                 mov x19, x0\n\
                 mov x20, x1\n\
                 mov x21, #0\n\
                 mov x22, #0\n\
                 mov x9, #0\n\
                 mov x10, #0\n\
                 adrp x27, _lsharp_root_stack@PAGE\n\
                 add x27, x27, _lsharp_root_stack@PAGEOFF\n\
                 mov x28, x27\n\
                 bl _generated\n\
                 ldp x27, x28, [sp, #48]\n\
                 ldp x21, x22, [sp, #32]\n\
                 ldp x19, x20, [sp, #16]\n\
                 ldp x29, x30, [sp], #80\n\
                 ret\n\
             .zerofill __DATA,__bss,_lsharp_root_stack,0x800000,3\n",
            byte_strs.join(", ")
        );
        std::fs::write(dir.join("prog.s"), &asm_content)
            .map_err(|e| format!("prog.s 書き込み失敗: {e}"))?;

        let link_result = std::process::Command::new("clang")
            .args(["-arch", "arm64", "prog.s", "-o", "prog"])
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("clang 実行失敗: {e}"))?;

        if !link_result.status.success() {
            return Err(format!(
                "リンク失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&link_result.stdout),
                String::from_utf8_lossy(&link_result.stderr),
            ));
        }

        let run_result = std::process::Command::new(dir.join("prog"))
            .args(args)
            .output()
            .map_err(|e| format!("実行失敗: {e}"))?;

        Ok(NativeHostExecutionResult {
            exit_code: run_result.status.code().unwrap_or(-1),
            stdout: run_result.stdout,
            stderr: run_result.stderr,
        })
    })();

    if keep_dir {
        eprintln!("kept native host exec dir: {}", dir.display());
    } else {
        let _ = std::fs::remove_dir_all(&dir);
    }
    result
}

