/// canonical artifact 名で object / response / binary を materialize し、実行まで行う。
fn materialize_native_host_bundle_artifacts_in_dir(
    dir: &std::path::Path,
    code: &[u8],
) -> Result<String, String> {
    let byte_strs: Vec<String> = code.iter().map(|b| format!("0x{b:02x}")).collect();
    let program_asm = format!(
        ".section __TEXT,__text\n\
             .globl _generated\n\
             _generated:\n\
                  .byte {}\n\
             .globl _main\n\
             _main:\n\
                 stp x21, x22, [sp, #-32]!\n\
                 str x30, [sp, #16]\n\
                 mov x19, x0\n\
                 mov x20, x1\n\
                 mov x21, #0\n\
                 mov x22, #0\n\
                 bl _generated\n\
                 ldr x30, [sp, #16]\n\
                 ldp x21, x22, [sp], #32\n\
                 ret\n",
        byte_strs.join(", ")
    );
    std::fs::write(dir.join("program.s"), program_asm)
        .map_err(|e| format!("program.s 書き込み失敗: {e}"))?;

    let runtime_asm =
        ".section __TEXT,__text\n.globl _lsharp_runtime_stub\n_lsharp_runtime_stub:\n    ret\n";
    std::fs::write(dir.join("runtime.s"), runtime_asm)
        .map_err(|e| format!("runtime.s 書き込み失敗: {e}"))?;

    let compile_program = std::process::Command::new("clang")
        .args(["-arch", "arm64", "-c", "program.s", "-o", "program.o"])
        .current_dir(dir)
        .output()
        .map_err(|e| format!("program.o 生成失敗: {e}"))?;
    if !compile_program.status.success() {
        return Err(format!(
            "program.o 生成失敗:\nstdout: {}\nstderr: {}",
            String::from_utf8_lossy(&compile_program.stdout),
            String::from_utf8_lossy(&compile_program.stderr),
        ));
    }

    let compile_runtime = std::process::Command::new("clang")
        .args(["-arch", "arm64", "-c", "runtime.s", "-o", "runtime.o"])
        .current_dir(dir)
        .output()
        .map_err(|e| format!("runtime.o 生成失敗: {e}"))?;
    if !compile_runtime.status.success() {
        return Err(format!(
            "runtime.o 生成失敗:\nstdout: {}\nstderr: {}",
            String::from_utf8_lossy(&compile_runtime.stdout),
            String::from_utf8_lossy(&compile_runtime.stderr),
        ));
    }

    let response_text = "-o\nprogram.native\nprogram.o\nruntime.o\n".to_string();
    std::fs::write(dir.join("linker-response.txt"), &response_text)
        .map_err(|e| format!("linker-response.txt 書き込み失敗: {e}"))?;

    let link_result = std::process::Command::new("clang")
        .arg("-Wl,-stack_size,0x08000000")
        .arg("@linker-response.txt")
        .current_dir(dir)
        .output()
        .map_err(|e| format!("clang response-file 実行失敗: {e}"))?;
    if !link_result.status.success() {
        return Err(format!(
            "canonical response-file link 失敗:\nstdout: {}\nstderr: {}",
            String::from_utf8_lossy(&link_result.stdout),
            String::from_utf8_lossy(&link_result.stderr),
        ));
    }

    let relink_result = std::process::Command::new("clang")
        .arg("-Wl,-stack_size,0x08000000")
        .arg("@linker-response.txt")
        .current_dir(dir)
        .output()
        .map_err(|e| format!("clang stack-size relink 実行失敗: {e}"))?;
    if !relink_result.status.success() {
        return Err(format!(
            "canonical stack-size relink 失敗:\nstdout: {}\nstderr: {}",
            String::from_utf8_lossy(&relink_result.stdout),
            String::from_utf8_lossy(&relink_result.stderr),
        ));
    }

    Ok(response_text)
}

fn read_native_host_bundle_from_dir(
    dir: &std::path::Path,
    response_text: String,
    stdout: Vec<u8>,
    stderr: Vec<u8>,
    exit_code: i32,
) -> Result<NativeHostArtifactBundle, String> {
    Ok(NativeHostArtifactBundle {
        program_object: std::fs::read(dir.join("program.o"))
            .map_err(|e| format!("program.o 読み込み失敗: {e}"))?,
        runtime_object: std::fs::read(dir.join("runtime.o"))
            .map_err(|e| format!("runtime.o 読み込み失敗: {e}"))?,
        response_text,
        program_binary: std::fs::read(dir.join("program.native"))
            .map_err(|e| format!("program.native 読み込み失敗: {e}"))?,
        stdout,
        stderr,
        exit_code,
    })
}

fn build_and_run_native_host_bundle_with_canonical_artifacts(
    code: &[u8],
) -> Result<NativeHostArtifactBundle, String> {
    if !host_native_exec_supported() {
        return Err(
            "canonical host bundle materialization は macOS arm64 でのみサポート".to_string(),
        );
    }

    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir("e2e-native-fixtures", "native-host-bundle", id);
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        let response_text = materialize_native_host_bundle_artifacts_in_dir(&dir, code)?;

        let run_result = std::process::Command::new(dir.join("program.native"))
            .output()
            .map_err(|e| format!("program.native 実行失敗: {e}"))?;

        read_native_host_bundle_from_dir(
            &dir,
            response_text,
            run_result.stdout,
            run_result.stderr,
            run_result.status.code().unwrap_or(-1),
        )
    })();

    let _ = std::fs::remove_dir_all(&dir);
    result
}

fn native_host_bundle_alloc_size(data_frontier: usize) -> usize {
    data_frontier
        .max(0x0001_0000)
        .saturating_add(0x1_0000_0000)
        .max(0x1_0000_0000)
}

fn build_native_host_bundle_with_canonical_artifacts_and_entrypoint(
    code: &[u8],
    data: &[u8],
    entrypoint_offset: usize,
) -> Result<NativeHostArtifactBundle, String> {
    if !host_native_exec_supported() {
        return Err(
            "canonical host bundle materialization は macOS arm64 でのみサポート".to_string(),
        );
    }
    if entrypoint_offset > code.len() {
        return Err(format!(
            "entrypoint offset が code bytes 範囲外: offset={} len={}",
            entrypoint_offset,
            code.len()
        ));
    }
    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir(
        "e2e-native-fixtures",
        "native-host-bundle-artifact-entrypoint",
        id,
    );
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        let align_up = |value: usize, alignment: usize| {
            if value == 0 {
                0
            } else {
                value.div_ceil(alignment) * alignment
            }
        };
        let prefix_bytes = &code[..entrypoint_offset];
        let suffix_bytes = &code[entrypoint_offset..];
        let data_base = 1024usize;
        let data_frontier = align_up(data_base.saturating_add(data.len()), 8);
        let alloc_size = native_host_bundle_alloc_size(data_frontier);
        let prefix_text = if prefix_bytes.is_empty() {
            "0x1f, 0x20, 0x03, 0xd5".to_string()
        } else {
            prefix_bytes
                .iter()
                .map(|b| format!("0x{b:02x}"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let suffix_text = suffix_bytes
            .iter()
            .map(|b| format!("0x{b:02x}"))
            .collect::<Vec<_>>()
            .join(", ");
        let data_text = if data.is_empty() {
            "0x00".to_string()
        } else {
            data.iter()
                .map(|b| format!("0x{b:02x}"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let program_asm = format!(
            ".section __TEXT,__text\n\
             .extern _calloc\n\
             .extern _memcpy\n\
             .extern _strlen\n\
             .globl _main\n\
             _main:\n\
                 stp x29, x30, [sp, #-112]!\n\
                 mov x29, sp\n\
                 stp x19, x20, [sp, #16]\n\
                 stp x21, x22, [sp, #32]\n\
                 stp x23, x24, [sp, #48]\n\
                 stp x25, x26, [sp, #64]\n\
                 stp x27, x28, [sp, #80]\n\
                 mov x19, x0\n\
                 mov x20, x1\n\
                 mov x0, #1\n\
                 adrp x8, _lsharp_alloc_size@PAGE\n\
                 ldr x1, [x8, _lsharp_alloc_size@PAGEOFF]\n\
                 bl _calloc\n\
                 cbz x0, _lsharp_alloc_fail\n\
                 mov x21, x0\n\
                 adrp x8, _lsharp_heap_frontier@PAGE\n\
                 ldr x22, [x8, _lsharp_heap_frontier@PAGEOFF]\n\
                 adrp x8, _lsharp_data_len@PAGE\n\
                 ldr x2, [x8, _lsharp_data_len@PAGEOFF]\n\
                  cbz x2, _lsharp_copy_argv\n\
                  add x0, x21, #{data_base}\n\
                  adrp x1, _lsharp_data@PAGE\n\
                  add x1, x1, _lsharp_data@PAGEOFF\n\
                  bl _memcpy\n\
              _lsharp_copy_argv:\n\
                  mov x23, x20\n\
                  add x25, x21, x22\n\
                  lsl x8, x19, #3\n\
                  add x8, x8, #7\n\
                  lsr x8, x8, #3\n\
                  lsl x8, x8, #3\n\
                  add x22, x22, x8\n\
                  mov x26, #0\n\
              _lsharp_copy_argv_loop:\n\
                  cmp x26, x19\n\
                  b.ge _lsharp_copy_argv_done\n\
                  ldr x24, [x23, x26, lsl #3]\n\
                  mov x0, x24\n\
                  bl _strlen\n\
                  mov x27, x0\n\
                  add x8, x27, #8\n\
                  add x8, x8, #7\n\
                  lsr x8, x8, #3\n\
                  lsl x8, x8, #3\n\
                  mov x28, x22\n\
                  add x22, x22, x8\n\
                  add x3, x21, x28\n\
                  mov w4, #1\n\
                  str w4, [x3]\n\
                  str w27, [x3, #4]\n\
                  add x0, x3, #8\n\
                  mov x1, x24\n\
                  mov x2, x27\n\
                  bl _memcpy\n\
                  mov x8, #-0x8000000000000000\n\
                  orr x8, x28, x8\n\
                  str x8, [x25, x26, lsl #3]\n\
                  add x26, x26, #1\n\
                  b _lsharp_copy_argv_loop\n\
              _lsharp_copy_argv_done:\n\
                  mov x20, x25\n\
              _lsharp_call_entry:\n\
                  mov x0, x19\n\
                  mov x1, x20\n\
                  mov x2, #0\n\
                  mov x3, #0\n\
                  mov x4, #0\n\
                  mov x5, #0\n\
                  mov x6, #0\n\
                  mov x7, #0\n\
                   mov x9, #0\n\
                   mov x10, #0\n\
                   adrp x27, _lsharp_root_stack@PAGE\n\
                   add x27, x27, _lsharp_root_stack@PAGEOFF\n\
                   mov x28, x27\n\
                   bl _lsharp_entry\n\
                    ldp x27, x28, [sp, #80]\n\
                    ldp x25, x26, [sp, #64]\n\
                    ldp x23, x24, [sp, #48]\n\
                    ldp x21, x22, [sp, #32]\n\
                    ldp x19, x20, [sp, #16]\n\
                    ldp x29, x30, [sp], #112\n\
                    ret\n\
               _lsharp_alloc_fail:\n\
                   mov w0, #1\n\
                   ldp x27, x28, [sp, #80]\n\
                   ldp x25, x26, [sp, #64]\n\
                   ldp x23, x24, [sp, #48]\n\
                   ldp x21, x22, [sp, #32]\n\
                   ldp x19, x20, [sp, #16]\n\
                   ldp x29, x30, [sp], #112\n\
                   ret\n\
             .section __TEXT,__const\n\
             .p2align 3\n\
             _lsharp_alloc_size:\n\
                 .quad {alloc_size}\n\
             _lsharp_heap_frontier:\n\
                 .quad {data_frontier}\n\
             _lsharp_data_len:\n\
                 .quad {data_len}\n\
             .section __TEXT,__text\n\
             .globl _lsharp_bundle\n\
             _lsharp_bundle:\n\
                  .byte {prefix_text}\n\
             .globl _lsharp_entry\n\
             _lsharp_entry:\n\
                 .byte {suffix_text}\n\
             .section __DATA,__data\n\
             .p2align 3\n\
             _lsharp_data:\n\
                 .byte {data_text}\n\
             .zerofill __DATA,__bss,_lsharp_root_stack,0x800000,3\n",
            alloc_size = alloc_size,
            data_base = data_base,
            data_frontier = data_frontier,
            data_len = data.len(),
            data_text = data_text,
        );
        std::fs::write(dir.join("program.s"), program_asm)
            .map_err(|e| format!("program.s 書き込み失敗: {e}"))?;

        let runtime_asm =
            ".section __TEXT,__text\n.globl _lsharp_runtime_stub\n_lsharp_runtime_stub:\n    ret\n";
        std::fs::write(dir.join("runtime.s"), runtime_asm)
            .map_err(|e| format!("runtime.s 書き込み失敗: {e}"))?;

        let compile_program = std::process::Command::new("clang")
            .args(["-arch", "arm64", "-c", "program.s", "-o", "program.o"])
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("program.o 生成失敗: {e}"))?;
        if !compile_program.status.success() {
            return Err(format!(
                "program.o 生成失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&compile_program.stdout),
                String::from_utf8_lossy(&compile_program.stderr),
            ));
        }

        let compile_runtime = std::process::Command::new("clang")
            .args(["-arch", "arm64", "-c", "runtime.s", "-o", "runtime.o"])
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("runtime.o 生成失敗: {e}"))?;
        if !compile_runtime.status.success() {
            return Err(format!(
                "runtime.o 生成失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&compile_runtime.stdout),
                String::from_utf8_lossy(&compile_runtime.stderr),
            ));
        }

        let response_text = "-o\nprogram.native\nprogram.o\nruntime.o\n".to_string();
        std::fs::write(dir.join("linker-response.txt"), &response_text)
            .map_err(|e| format!("linker-response.txt 書き込み失敗: {e}"))?;

        let link_result = std::process::Command::new("clang")
            .arg("-Wl,-stack_size,0x08000000")
            .arg("@linker-response.txt")
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("clang response-file 実行失敗: {e}"))?;
        if !link_result.status.success() {
            return Err(format!(
                "canonical response-file link 失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&link_result.stdout),
                String::from_utf8_lossy(&link_result.stderr),
            ));
        }

        let relink_result = std::process::Command::new("clang")
            .arg("-Wl,-stack_size,0x08000000")
            .arg("@linker-response.txt")
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("clang stack-size relink 実行失敗: {e}"))?;
        if !relink_result.status.success() {
            return Err(format!(
                "canonical stack-size relink 失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&relink_result.stdout),
                String::from_utf8_lossy(&relink_result.stderr),
            ));
        }

        read_native_host_bundle_from_dir(&dir, response_text, Vec::new(), Vec::new(), 0)
    })();

    let _ = std::fs::remove_dir_all(&dir);
    result
}

fn build_linux_x86_host_bundle_with_canonical_artifacts_and_entrypoint(
    code: &[u8],
    entrypoint_offset: usize,
) -> Result<NativeHostArtifactBundle, String> {
    if !linux_x86_native_exec_supported() {
        return Err(
            "Linux x86_64 host bundle materialization は Linux/x86_64 でのみサポート".to_string(),
        );
    }
    if entrypoint_offset > code.len() {
        return Err(format!(
            "entrypoint offset が code bytes 範囲外: offset={} len={}",
            entrypoint_offset,
            code.len()
        ));
    }

    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir(
        "e2e-native-fixtures",
        "linux-x86-host-bundle-artifact-entrypoint",
        id,
    );
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        let prefix_bytes = &code[..entrypoint_offset];
        let suffix_bytes = &code[entrypoint_offset..];
        let prefix_text = if prefix_bytes.is_empty() {
            "0x90".to_string()
        } else {
            prefix_bytes
                .iter()
                .map(|b| format!("0x{b:02x}"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let suffix_text = if suffix_bytes.is_empty() {
            "0xc3".to_string()
        } else {
            suffix_bytes
                .iter()
                .map(|b| format!("0x{b:02x}"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let program_asm = format!(
            ".text\n\
             .extern calloc\n\
             .extern malloc\n\
             .extern memcpy\n\
             .extern strlen\n\
             .globl main\n\
             main:\n\
                 push %rbp\n\
                 mov %rsp, %rbp\n\
                 push %rbx\n\
                 push %r12\n\
                 push %r13\n\
                 push %r14\n\
                 push %r15\n\
                 sub $24, %rsp\n\
                 mov %rdi, %r14\n\
                 mov %rsi, %r12\n\
                 mov %r14, %rdi\n\
                 mov $8, %rsi\n\
                 call calloc@PLT\n\
                 test %rax, %rax\n\
                 je .Lalloc_fail\n\
                 mov %rax, %r15\n\
                 xor %r13d, %r13d\n\
             .Largv_loop:\n\
                 cmp %r14, %r13\n\
                 jge .Largv_done\n\
                 mov (%r12,%r13,8), %rbx\n\
                 mov %rbx, %rdi\n\
                 call strlen@PLT\n\
                 mov %rax, -48(%rbp)\n\
                 lea 8(%rax), %rdi\n\
                 call malloc@PLT\n\
                 test %rax, %rax\n\
                 je .Lalloc_fail\n\
                 mov %rax, -56(%rbp)\n\
                 movl $1, (%rax)\n\
                 mov -48(%rbp), %rcx\n\
                 mov %ecx, 4(%rax)\n\
                 lea 8(%rax), %rdi\n\
                 mov %rbx, %rsi\n\
                 mov %rcx, %rdx\n\
                 call memcpy@PLT\n\
                 mov -56(%rbp), %rax\n\
                 movabs $0x8000000000000000, %rcx\n\
                 or %rcx, %rax\n\
                 mov %rax, (%r15,%r13,8)\n\
                 inc %r13\n\
                 jmp .Largv_loop\n\
             .Largv_done:\n\
                 call generated\n\
                 jmp .Ldone\n\
             .Lalloc_fail:\n\
                 mov $1, %eax\n\
             .Ldone:\n\
                 add $24, %rsp\n\
                 pop %r15\n\
                 pop %r14\n\
                 pop %r13\n\
                 pop %r12\n\
                 pop %rbx\n\
                 pop %rbp\n\
                 ret\n\
             .globl lsharp_bundle\n\
             lsharp_bundle:\n\
                 .byte {prefix_text}\n\
             .globl generated\n\
             generated:\n\
                 .byte {suffix_text}\n\
             .section .note.GNU-stack,\"\",@progbits\n",
            prefix_text = prefix_text,
            suffix_text = suffix_text,
        );
        std::fs::write(dir.join("program.s"), program_asm)
            .map_err(|e| format!("program.s 書き込み失敗: {e}"))?;

        let runtime_asm = ".text\n.globl lsharp_runtime_stub\nlsharp_runtime_stub:\n    ret\n.section .note.GNU-stack,\"\",@progbits\n";
        std::fs::write(dir.join("runtime.s"), runtime_asm)
            .map_err(|e| format!("runtime.s 書き込み失敗: {e}"))?;

        let compile_program = std::process::Command::new("cc")
            .args(["-c", "program.s", "-o", "program.o"])
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("program.o 生成失敗: {e}"))?;
        if !compile_program.status.success() {
            return Err(format!(
                "program.o 生成失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&compile_program.stdout),
                String::from_utf8_lossy(&compile_program.stderr),
            ));
        }

        let compile_runtime = std::process::Command::new("cc")
            .args(["-c", "runtime.s", "-o", "runtime.o"])
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("runtime.o 生成失敗: {e}"))?;
        if !compile_runtime.status.success() {
            return Err(format!(
                "runtime.o 生成失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&compile_runtime.stdout),
                String::from_utf8_lossy(&compile_runtime.stderr),
            ));
        }

        let response_text = "-o\nprogram.native\nprogram.o\nruntime.o\n".to_string();
        std::fs::write(dir.join("linker-response.txt"), &response_text)
            .map_err(|e| format!("linker-response.txt 書き込み失敗: {e}"))?;
        let link_result = std::process::Command::new("cc")
            .arg("@linker-response.txt")
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("cc response-file 実行失敗: {e}"))?;
        if !link_result.status.success() {
            return Err(format!(
                "Linux x86 response-file link 失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&link_result.stdout),
                String::from_utf8_lossy(&link_result.stderr),
            ));
        }

        read_native_host_bundle_from_dir(&dir, response_text, Vec::new(), Vec::new(), 0)
    })();

    let _ = std::fs::remove_dir_all(&dir);
    result
}

fn build_and_run_native_host_bundle_with_canonical_artifacts_and_entrypoint(
    code: &[u8],
    data: &[u8],
    entrypoint_offset: usize,
) -> Result<NativeHostArtifactBundle, String> {
    if !host_native_exec_supported() {
        return Err(
            "canonical host bundle materialization は macOS arm64 でのみサポート".to_string(),
        );
    }
    if entrypoint_offset > code.len() {
        return Err(format!(
            "entrypoint offset が code bytes 範囲外: offset={} len={}",
            entrypoint_offset,
            code.len()
        ));
    }

    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir(
        "e2e-native-fixtures",
        "native-host-bundle-artifact-entrypoint-exec",
        id,
    );
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        let bundle = build_native_host_bundle_with_canonical_artifacts_and_entrypoint(
            code,
            data,
            entrypoint_offset,
        )?;
        std::fs::write(dir.join("program.o"), &bundle.program_object)
            .map_err(|e| format!("program.o 書き込み失敗: {e}"))?;
        std::fs::write(dir.join("runtime.o"), &bundle.runtime_object)
            .map_err(|e| format!("runtime.o 書き込み失敗: {e}"))?;
        std::fs::write(dir.join("linker-response.txt"), &bundle.response_text)
            .map_err(|e| format!("linker-response.txt 書き込み失敗: {e}"))?;
        let program_binary_path = dir.join("program.native");
        let relink_result = std::process::Command::new("clang")
            .arg("-Wl,-stack_size,0x08000000")
            .arg("@linker-response.txt")
            .current_dir(&dir)
            .output()
            .map_err(|e| format!("final exec-dir relink 実行失敗: {e}"))?;
        if !relink_result.status.success() {
            return Err(format!(
                "final exec-dir relink 失敗:\nstdout: {}\nstderr: {}",
                String::from_utf8_lossy(&relink_result.stdout),
                String::from_utf8_lossy(&relink_result.stderr),
            ));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;

            let permissions = std::fs::Permissions::from_mode(0o755);
            std::fs::set_permissions(&program_binary_path, permissions)
                .map_err(|e| format!("program.native の execute bit 設定失敗: {e}"))?;
        }

        let run_result = std::process::Command::new(&program_binary_path)
            .output()
            .map_err(|e| format!("program.native 実行失敗: {e}"))?;

        read_native_host_bundle_from_dir(
            &dir,
            bundle.response_text,
            run_result.stdout,
            run_result.stderr,
            run_result.status.code().unwrap_or(-1),
        )
    })();

    let keep_dir = std::env::var_os("LSHARP_NATIVE_PROXY_KEEP_FAILED_DIR").is_some();
    let should_remove_dir = !keep_dir;
    if should_remove_dir {
        let _ = std::fs::remove_dir_all(&dir);
    }
    result
}

fn build_and_run_native_host_bundle_with_canonical_artifacts_and_entrypoint_and_representative_modules(
    code: &[u8],
    data: &[u8],
    entrypoint_offset: usize,
) -> Result<NativeHostArtifactBundle, String> {
    build_and_run_native_host_bundle_with_canonical_artifacts_and_entrypoint_and_representative_modules_with_args(
        code,
        data,
        entrypoint_offset,
        &[],
        &[],
    )
}

fn build_and_run_native_host_bundle_with_canonical_artifacts_and_entrypoint_and_representative_modules_with_args(
    code: &[u8],
    data: &[u8],
    entrypoint_offset: usize,
    args: &[String],
    extra_files: &[(&str, &str)],
) -> Result<NativeHostArtifactBundle, String> {
    if !host_native_exec_supported() {
        return Err(
            "canonical host bundle materialization は macOS arm64 でのみサポート".to_string(),
        );
    }

    let bundle = build_native_host_bundle_with_canonical_artifacts_and_entrypoint(
        code,
        data,
        entrypoint_offset,
    )?;
    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir(
        "e2e-native-fixtures",
        "native-host-bundle-artifact-entrypoint-representative-modules",
        id,
    );
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;

    let result = (|| {
        std::fs::write(dir.join("program.o"), &bundle.program_object)
            .map_err(|e| format!("program.o 書き込み失敗: {e}"))?;
        std::fs::write(dir.join("runtime.o"), &bundle.runtime_object)
            .map_err(|e| format!("runtime.o 書き込み失敗: {e}"))?;
        std::fs::write(dir.join("linker-response.txt"), &bundle.response_text)
            .map_err(|e| format!("linker-response.txt 書き込み失敗: {e}"))?;
        let program_binary_path = dir.join("program.native");
        std::fs::write(&program_binary_path, &bundle.program_binary)
            .map_err(|e| format!("program.native 書き込み失敗: {e}"))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;

            let permissions = std::fs::Permissions::from_mode(0o755);
            std::fs::set_permissions(&program_binary_path, permissions)
                .map_err(|e| format!("program.native の execute bit 設定失敗: {e}"))?;
        }
        write_representative_selfhost_modules_for_native_stage(&dir)?;
        for (relative_path, contents) in extra_files {
            let path = dir.join(relative_path);
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent)
                    .map_err(|e| format!("{}: {e}", parent.display()))?;
            }
            std::fs::write(&path, contents).map_err(|e| format!("{}: {e}", path.display()))?;
        }
        let path_args = args.to_vec();

        let run_result = std::process::Command::new(&program_binary_path)
            .current_dir(&dir)
            .args(&path_args)
            .output()
            .map_err(|e| format!("program.native 実行失敗: {e}"))?;
        read_native_host_bundle_from_dir(
            &dir,
            bundle.response_text.clone(),
            run_result.stdout,
            run_result.stderr,
            run_result.status.code().unwrap_or(-1),
        )
    })();

    let keep_dir = std::env::var_os("LSHARP_NATIVE_PROXY_KEEP_FAILED_DIR").is_some();
    if !keep_dir {
        let _ = std::fs::remove_dir_all(&dir);
    }
    result
}

fn try_compile_and_run_representative_override_main_with_path_arg(
    _label: &str,
    main_source: &str,
    relative_path_arg: &str,
) -> Result<String, String> {
    let id = NATIVE_HOST_EXEC_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = target_fixture_dir("e2e-native-fixtures", "representative-override-main", id);
    std::fs::create_dir_all(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    let result = (|| {
        write_representative_selfhost_modules_for_native_stage(&dir)?;
        let entry_path = dir.join("src/App/OverrideMain.ls");
        if let Some(parent) = entry_path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| format!("{}: {e}", parent.display()))?;
        }
        std::fs::write(&entry_path, main_source)
            .map_err(|e| format!("{}: {e}", entry_path.display()))?;
        let wasm = try_compile_file_only(&entry_path)?;
        wasmparser::Validator::new()
            .validate_all(&wasm)
            .map_err(|e| format!("Wasm validate: {e}"))?;
        let args = ["program.native", relative_path_arg];
        lsharp_wasm::wasi_runner::run_wasm_wasi_with_dir_and_args(&wasm, Some(&dir), &args)
            .map_err(|e| format!("実行: {e:?}"))
    })();
    let _ = std::fs::remove_dir_all(&dir);
    result
}

fn align_aarch64_entrypoint_to_function_start(code: &[u8], entrypoint_offset: usize) -> usize {
    if entrypoint_offset >= code.len() {
        return entrypoint_offset;
    }

    entrypoint_offset
}

#[test]
fn test_align_aarch64_entrypoint_to_function_start_preserves_leaf_start_without_prologue() {
    let code = vec![
        0x1f, 0x20, 0x03, 0xd5, // nop
        0xfd, 0x7b, 0xbf, 0xa9, // stp x29, x30, [sp, #-16]!
        0xff, 0x43, 0x03, 0xd1, // sub sp, sp, #0xd0
        0xe0, 0x03, 0x00, 0xaa, // mov x0, x0
        0xc0, 0x03, 0x5f, 0xd6, // ret
        0x00, 0x00, 0x80, 0x52, // mov w0, #0
        0xc0, 0x03, 0x5f, 0xd6, // ret
    ];

    assert_eq!(
        align_aarch64_entrypoint_to_function_start(&code, 20),
        20,
        "AArch64 entrypoint は prologue のない leaf 関数先頭をそのまま使うべき"
    );
}

/// NATIVE-HOST-01: stage1-native-emitted object をホスト (aarch64-apple-darwin) でリンク・実行する
///
/// stage1 (Wasm で動く L# コンパイラ) が `host-target()` (aarch64-apple-darwin) 向けに
/// 生成したネイティブコードバイト列を clang (arm64) でリンクし、実行する。
/// 正しい AArch64 コードが生成されていれば exit code 42 が返る。
///
/// RED: NativeCodegen.ls が aarch64 向けに x86_64 コードを生成するため失敗する。
/// GREEN: NativeCodegen.ls に AArch64 命令生成を追加し、aarch64 target で MOVZ W0, #42 + RET が
///        生成されることで exit code 42 を得られる。
#[test]
#[ignore]
fn test_e2e_native_host_binary_link_and_execute() {
    if !host_native_exec_supported() {
        return;
    }

    let code_bytes = host_target_const_42_code_bytes();

    assert!(
        !code_bytes.is_empty(),
        "stage1-native: host target 向けコードバイト列が空"
    );

    // ホスト (aarch64-apple-darwin) でリンク・実行して exit code 42 を確認
    let exit_code =
        link_and_run_native_host_binary(&code_bytes).expect("host binary リンク・実行に失敗");

    assert_eq!(
        exit_code,
        42,
        "host binary: exit code 42 を期待したが {} を得た\n\
         bytes ({} bytes): {:?}",
        exit_code,
        code_bytes.len(),
        code_bytes
    );
}

/// NATIVE-LINUX-X86-01: Linux x86_64 VM 上で x86_64 backend の const-42 contract bytes をリンク・実行する。
#[test]
#[ignore]
fn test_e2e_native_linux_x86_const_42_link_and_execute() {
    if !linux_x86_native_exec_supported() {
        return;
    }

    let code_bytes = linux_x86_const_42_code_bytes();

    assert!(
        !code_bytes.is_empty(),
        "stage1-native: Linux x86_64 target 向けコードバイト列が空"
    );

    let exit_code = link_and_run_linux_x86_native_binary(&code_bytes)
        .expect("Linux x86_64 native binary リンク・実行に失敗");

    assert_eq!(
        exit_code,
        42,
        "Linux x86_64 native binary: exit code 42 を期待したが {} を得た\n\
         bytes ({} bytes): {:?}",
        exit_code,
        code_bytes.len(),
        code_bytes
    );
}

