#[test]
#[ignore]
fn test_e2e_selfhost_main_linux_x86_actual_seed_start_window_diagnostic() {
    let start_offset: i64 = std::env::var("LSHARP_NATIVE_LINUX_X86_START_OFFSET_START")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(931000);
    let end_offset: i64 = std::env::var("LSHARP_NATIVE_LINUX_X86_START_OFFSET_END")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(933500);
    let nearest_offset: i64 = std::env::var("LSHARP_NATIVE_LINUX_X86_START_NEAREST_OFFSET")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(-1);
    assert!(
        start_offset < end_offset,
        "LSHARP_NATIVE_LINUX_X86_START_OFFSET_START は START_OFFSET_END より小さい必要がある: {start_offset}..{end_offset}"
    );
    let seed_source = linux_x86_representative_actual_stage23_seed_source();
    let escaped_seed_source = escape_lsharp_string(&seed_source);
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/Seed.ls" "{escaped_seed_source}")
            (compile-file-functions-payload-with-cache "src/App/Seed.ls" 10 cache-ref parse-count-ref))"#
    );
    let harness = format!(
        r#"(module App.HarnessMain)
(import App.CompilerMode)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn push-import-placeholders [idx count result]
  (if (>= idx count)
    result
    (push-import-placeholders
      (+ idx 1)
      count
      (vector-push result (make-function-meta 0 0 (vector-new 0))))))

(defn append-vector-loop [dst src idx len]
  (if (>= idx len)
    dst
    (append-vector-loop
      (vector-push dst (vector-get src idx))
      src
      (+ idx 1)
      len)))

(defn x86-function-slot-size [func-meta functions]
  (+ (native-function-size-x86 func-meta functions) 2048))

(defn collect-callable-function-slot-starts-x86-loop [functions idx len starts offset]
  (if (>= idx len)
    starts
    (let [func-meta (vector-get functions idx)
          next-starts (vector-push starts offset)
          next-offset (+ offset (x86-function-slot-size func-meta functions))]
      (collect-callable-function-slot-starts-x86-loop functions (+ idx 1) len next-starts next-offset))))

(defn collect-callable-function-slot-starts-x86 [functions import-count]
  (collect-callable-function-slot-starts-x86-loop functions import-count (vector-length functions) (vector-new 8) 0))

(defn start-at-or-minus-one [starts idx len]
  (if (>= idx len)
    -1
    (vector-get starts idx)))

(defn print-nearest-start-owner [functions starts idx len nearest best-idx best-start]
  (if (>= idx len)
    (if (< best-idx 0)
      (do
        (print -9001)
        (print -1)
        (print -1)
        (print -1)
        (print -1)
        (print -1)
        (print -1)
        (print -1)
        (print -1)
        (print -1)
        0)
      (let [func (vector-get functions (+ best-idx 10))
            next-start (start-at-or-minus-one starts (+ best-idx 1) len)]
        (do
          (print -9001)
          (print best-idx)
          (print (+ best-idx 10))
          (print best-start)
          (print next-start)
          (print (- nearest best-start))
          (print (native-function-size-x86 func functions))
          (print (native-function-param-count func))
          (print (native-function-local-count func))
          (print (vector-length (native-function-ir func)))
          0)))
    (let [start (vector-get starts idx)
          use-current (and (<= start nearest) (> start best-start))
          next-best-idx (if use-current idx best-idx)
          next-best-start (if use-current start best-start)]
      (print-nearest-start-owner functions starts (+ idx 1) len nearest next-best-idx next-best-start))))

(defn print-start-window [functions starts idx len]
  (if (>= idx len)
    0
    (let [start (vector-get starts idx)]
      (if (and (>= start {start_offset}) (< start {end_offset}))
        (let [func (vector-get functions (+ idx 10))]
          (do
            (print idx)
            (print (+ idx 10))
            (print start)
            (print (native-function-size-x86 func functions))
            (print (native-function-param-count func))
            (print (native-function-local-count func))
            (print (vector-length (native-function-ir func)))
            (print-start-window functions starts (+ idx 1) len)))
        (print-start-window functions starts (+ idx 1) len)))))

(defn main []
  (let [cache-ref (ref-new (map-new))
        parse-count-ref (ref-new 0)
        payload {payload_expr}
        functions (vector-get payload 0)
        callables (append-vector-loop (push-import-placeholders 0 10 (vector-new 32)) functions 0 (vector-length functions))
        target (make-target 3)
        native-callables (normalize-selfhost-native-function-metas-for-target callables target)
        starts (collect-callable-function-slot-starts-x86 native-callables 10)]
    (let [window-result (print-start-window native-callables starts 0 (vector-length starts))]
      (if (>= {nearest_offset} 0)
        (print-nearest-start-owner native-callables starts 0 (vector-length starts) {nearest_offset} -1 -1)
        window-result))))"#,
        payload_expr = payload_expr,
        start_offset = start_offset,
        end_offset = end_offset,
        nearest_offset = nearest_offset
    );
    let output = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        try_compile_and_run_selfhost_fixture_entry_with_dir_and_args(
            "linux-x86-actual-seed-start-window-diagnostic",
            SELFHOST_APP_MAIN_REPRESENTATIVE_MODULES,
            "src/App/HarnessMain.ls",
            &harness,
            &[],
        )
    })
    .expect("Linux x86 actual seed start window diagnostic 実行に失敗");
    let lines = parse_numeric_lines(&output);
    println!("Linux x86 actual seed start window lines: {lines:?}");
    assert!(
        !lines.is_empty(),
        "Linux x86 actual seed start window diagnostic 出力が空"
    );
}

#[test]
#[ignore]
fn test_e2e_selfhost_main_linux_x86_actual_seed_function_offsets_diagnostic() {
    let func_idx: i64 = std::env::var("LSHARP_NATIVE_LINUX_X86_FUNCTION_INDEX")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(1222);
    assert!(
        func_idx >= 10,
        "LSHARP_NATIVE_LINUX_X86_FUNCTION_INDEX は import prefix 10 以上であるべき: {func_idx}"
    );
    let start_idx = func_idx - 10;
    let offset_start: i64 = std::env::var("LSHARP_NATIVE_LINUX_X86_OFFSET_START")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(0);
    let offset_end: i64 = std::env::var("LSHARP_NATIVE_LINUX_X86_OFFSET_END")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(9_999_999_999);
    assert!(
        offset_start < offset_end,
        "LSHARP_NATIVE_LINUX_X86_OFFSET_START は OFFSET_END より小さい必要がある: {offset_start}..{offset_end}"
    );
    let seed_source = linux_x86_representative_actual_stage23_seed_source();
    let escaped_seed_source = escape_lsharp_string(&seed_source);
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/Seed.ls" "{escaped_seed_source}")
            (compile-file-functions-payload-with-cache "src/App/Seed.ls" 10 cache-ref parse-count-ref))"#
    );
    let harness = format!(
        r#"(module App.HarnessMain)
	(import App.CompilerMode)
	(import Backend.Native.NativeTarget)
	(import Backend.Native.NativeCodegen)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn push-import-placeholders [idx count result]
  (if (>= idx count)
    result
    (push-import-placeholders
      (+ idx 1)
      count
      (vector-push result (make-function-meta 0 0 (vector-new 0))))))

(defn append-vector-loop [dst src idx len]
  (if (>= idx len)
    dst
    (append-vector-loop
      (vector-push dst (vector-get src idx))
      src
      (+ idx 1)
      len)))

(defn call-target-offset [operand starts import-count import-stub-offset function-start-base]
  (if (< operand import-count)
    (- (x86-import-ret-stub-offset import-stub-offset import-count operand) function-start-base)
    (- (vector-get starts (- operand import-count)) function-start-base)))

(defn runtime-target-offset [opcode import-count import-stub-offset function-start-base]
  (if (= opcode 60)
    (- (x86-selfhost-map-new-helper-offset import-stub-offset import-count) function-start-base)
    (if (= opcode 56)
      (- (x86-selfhost-ref-new-helper-offset import-stub-offset import-count) function-start-base)
      (if (= opcode 67)
        (- (x86-selfhost-command-line-arg-helper-offset import-stub-offset import-count) function-start-base)
        -1))))

(defn diagnostic-target-offset [opcode operand starts functions import-count import-stub-offset function-start-base]
  (if (= opcode 40)
    (call-target-offset operand starts import-count import-stub-offset function-start-base)
    (runtime-target-offset opcode import-count import-stub-offset function-start-base)))

(defn diagnostic-param-count [opcode operand functions]
  (if (= opcode 40)
    (native-function-param-count (vector-get functions operand))
    -1))

(defn x86-param-spill-prefix-size [param-count]
  (if (>= param-count 20)
    (native-param-spill-bytes-x86-twenty-plus param-count)
    (if (> param-count 6)
      (+ 53 (* (- param-count 7) 11))
      (if (= param-count 6)
        42
        (if (= param-count 5)
          35
          (if (= param-count 4)
            28
            (if (= param-count 3)
              21
              (if (= param-count 2)
                14
                (if (= param-count 1) 7 0)))))))))

(defn x86-function-slot-size [func-meta functions]
  (+ (native-function-size-x86 func-meta functions) 2048))

(defn collect-callable-function-slot-starts-x86-loop [functions idx len starts offset]
  (if (>= idx len)
    starts
    (let [func-meta (vector-get functions idx)
          next-starts (vector-push starts offset)
          next-offset (+ offset (x86-function-slot-size func-meta functions))]
      (collect-callable-function-slot-starts-x86-loop functions (+ idx 1) len next-starts next-offset))))

(defn collect-callable-function-slot-starts-x86 [functions import-count]
  (collect-callable-function-slot-starts-x86-loop functions import-count (vector-length functions) (vector-new 8) 0))

(defn callable-user-total-slot-size-x86-loop [functions idx len total]
  (if (>= idx len)
    total
    (let [func-meta (vector-get functions idx)
          next-total (+ total (x86-function-slot-size func-meta functions))]
      (callable-user-total-slot-size-x86-loop functions (+ idx 1) len next-total))))

(defn callable-user-total-slot-size-x86 [functions import-count]
  (callable-user-total-slot-size-x86-loop functions import-count (vector-length functions) 0))

(defn print-instr-offsets [ir functions starts import-count import-stub-offset function-start-base offsets idx len depth]
  (if (>= idx len)
    0
    (let [instr (vector-get ir idx)
          opcode (vector-get instr 0)
          operand (vector-get instr 1)
          current-offset (vector-get offsets idx)
          relative-offset (- current-offset function-start-base)
          size (native-instr-size-x86 opcode operand functions depth)]
      (if (or
            (and (>= current-offset {offset_start}) (< current-offset {offset_end}))
            (and (>= relative-offset {offset_start}) (< relative-offset {offset_end})))
        (do
          (print idx)
          (print opcode)
          (print operand)
          (print depth)
          (print current-offset)
          (print size)
          (print (diagnostic-param-count opcode operand functions))
          (print (diagnostic-target-offset opcode operand starts functions import-count import-stub-offset function-start-base))
          (print-instr-offsets ir functions starts import-count import-stub-offset function-start-base offsets (+ idx 1) len (apply-stack-delta depth (opcode-stack-delta opcode operand functions))))
        (print-instr-offsets ir functions starts import-count import-stub-offset function-start-base offsets (+ idx 1) len (apply-stack-delta depth (opcode-stack-delta opcode operand functions)))))))

(defn main []
  (let [cache-ref (ref-new (map-new))
        parse-count-ref (ref-new 0)
        payload {payload_expr}
        functions (vector-get payload 0)
	        callables (append-vector-loop (push-import-placeholders 0 10 (vector-new 32)) functions 0 (vector-length functions))
	        target (make-target 3)
	        native-callables (normalize-selfhost-native-function-metas-for-target callables target)
        starts (collect-callable-function-slot-starts-x86 native-callables 10)
        import-stub-offset (callable-user-total-slot-size-x86 native-callables 10)
        function-start-base (vector-get starts {start_idx})
        func (vector-get native-callables {func_idx})
        ir (native-function-ir func)
        frame-base-slot-count
          (native-frame-base-slot-count
            ir
            (+ (+ (native-function-param-count func) (native-function-local-count func)) 1))
        body-offset (+ (+ function-start-base 4)
          (+ (if (> (native-local-stack-bytes-with-window-x86
                       ir
                       (+ (+ (native-function-param-count func) (native-function-local-count func)) 1)
                       native-callables)
                    0)
               7
               0)
             (x86-param-spill-prefix-size (native-function-param-count func))))
        offsets (collect-native-bundle-offsets-x86 ir native-callables body-offset)]
    (do
      (print {func_idx})
      (print {start_idx})
      (print function-start-base)
      (print (native-function-size-x86 func native-callables))
      (print frame-base-slot-count)
      (print body-offset)
      (print-instr-offsets ir native-callables starts 10 import-stub-offset function-start-base offsets 0 (vector-length ir) 0))))"#,
        payload_expr = payload_expr,
        func_idx = func_idx,
        start_idx = start_idx,
        offset_start = offset_start,
        offset_end = offset_end
    );
    let label = format!("linux-x86-actual-seed-function-{func_idx}-offsets-diagnostic");
    let output = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        try_compile_and_run_selfhost_fixture_entry_with_dir_and_args(
            &label,
            SELFHOST_APP_MAIN_REPRESENTATIVE_MODULES,
            "src/App/HarnessMain.ls",
            &harness,
            &[],
        )
    })
    .expect("Linux x86 actual seed function offsets diagnostic 実行に失敗");
    let lines = parse_numeric_lines(&output);
    println!("Linux x86 actual seed function {func_idx} offset lines: {lines:?}");
    assert!(
        lines.len() >= 6,
        "Linux x86 actual seed function offsets diagnostic header が不足: {lines:?}"
    );
    assert_eq!(
        lines[0], func_idx,
        "diagnostic が指定 function index を出力していない: {lines:?}"
    );
    assert_eq!(
        lines[1], start_idx,
        "diagnostic が指定 start index を出力していない: {lines:?}"
    );
    assert!(
        (lines.len() - 6).is_multiple_of(8),
        "Linux x86 actual seed function offsets diagnostic row は 8 値単位であるべき: {lines:?}"
    );
    let rows = lines[6..]
        .chunks_exact(8)
        .map(|row| X86IrCallTraceRow {
            instr_idx: row[0],
            opcode: row[1],
            operand: row[2],
            depth: row[3],
            offset: row[4],
            size: row[5],
            param_count: row[6],
            target_offset: row[7],
        })
        .collect::<Vec<_>>();
    assert!(
        !rows.is_empty(),
        "指定 offset window に IR row が無い: function={func_idx} offset_window={offset_start}..{offset_end} absolute-or-relative header={:?}",
        &lines[..6]
    );
    if let Some(stage2_dir) = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE2_ARTIFACT_DIR") {
        let stage2_dir = workspace_root_relative_path(std::path::PathBuf::from(stage2_dir));
        let stage2_bundle = read_linux_x86_stage_code_artifact_bundle(
            &stage2_dir,
            &["stage-code.bin", "stage2-code.bin"],
            &["stage-data.bin", "stage2-data.bin"],
        );
        let function_start_base = lines[2];
        let declared_start = function_start_base as usize;
        let declared_body_start = lines[5] as usize;
        let actual_function_segment = {
            let segments_path = stage2_dir.join("stage-code-segments.tsv");
            if segments_path.exists() {
                let segments = read_linux_x86_stage_code_segments_tsv(&segments_path);
                find_linux_x86_transport_segment_for_function_idx(&segments, func_idx as usize)
                    .cloned()
            } else {
                None
            }
        };
        if let Some(segment) = actual_function_segment.as_ref() {
            let segment_drift = segment.start as i64 - function_start_base;
            println!(
                "Linux x86 function actual segment mapping: function={func_idx} declared_start={declared_start} actual_segment={segment:?} segment_drift={segment_drift} declared_body_start={declared_body_start} actual_segment_window={}",
                byte_window_hex(&stage2_bundle.code_bytes, segment.start, 0, 128)
            );
        }
        if let Some(actual_prologue_start) =
            nearest_x86_prologue_start(&stage2_bundle.code_bytes, declared_start, 96, 96)
        {
            let prologue_drift = actual_prologue_start as i64 - declared_start as i64;
            println!(
                "Linux x86 function prologue window: function={func_idx} declared_start={declared_start} actual_prologue_start={actual_prologue_start} prologue_drift={prologue_drift} declared_body_start={declared_body_start} declared_window={} actual_window={}",
                byte_window_hex(&stage2_bundle.code_bytes, declared_start, 32, 96),
                byte_window_hex(&stage2_bundle.code_bytes, actual_prologue_start, 0, 128)
            );
        } else {
            println!(
                "Linux x86 function prologue window: function={func_idx} declared_start={declared_start} actual_prologue_start=-1 prologue_drift=unavailable declared_body_start={declared_body_start} declared_window={}",
                byte_window_hex(&stage2_bundle.code_bytes, declared_start, 96, 128)
            );
        }
        for row in &rows {
            if row.offset < 0 {
                continue;
            }
            let relative_offset = row.offset - function_start_base;
            assert!(
                relative_offset >= 0,
                "diagnostic row offset が function start より前: row={row:?} function_start={function_start_base}"
            );
            let offset = actual_function_segment
                .as_ref()
                .map(|segment| segment.start + relative_offset as usize)
                .unwrap_or(row.offset as usize);
            assert!(
                offset < stage2_bundle.code_bytes.len(),
                "diagnostic row offset が stage2 code 範囲外: row={row:?} relative_offset={relative_offset} mapped_offset={offset} len={}",
                stage2_bundle.code_bytes.len()
            );
            let row_end = (offset + row.size.max(1) as usize).min(stage2_bundle.code_bytes.len());
            let call_sites = (offset..row_end.saturating_sub(4))
                .filter(|candidate| stage2_bundle.code_bytes[*candidate] == 0xe8)
                .map(|candidate| decode_x86_rel32_call_at(&stage2_bundle.code_bytes, candidate))
                .collect::<Vec<_>>();
            println!(
                "Linux x86 function {func_idx} row bytes: row={row:?} relative_offset={relative_offset} mapped_offset={offset} target_mapped_offset={} bytes={} calls={call_sites:?}",
                if row.target_offset >= 0 {
                    actual_function_segment
                        .as_ref()
                        .map(|segment| segment.start as i64 + row.target_offset)
                        .unwrap_or(row.target_offset)
                } else {
                    -1
                },
                byte_window_hex(
                    &stage2_bundle.code_bytes,
                    offset,
                    0,
                    row.size.max(1) as usize
                )
            );
        }
    }
}

#[test]
#[ignore]
fn test_e2e_selfhost_main_linux_x86_actual_seed_owner_decl_diagnostic() {
    let target_idx: i64 = std::env::var("LSHARP_NATIVE_LINUX_X86_OWNER_FUNCTION_INDEX")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(1472);
    let seed_source = linux_x86_representative_actual_stage23_seed_source();
    let escaped_seed_source = escape_lsharp_string(&seed_source);
    let harness = format!(
        r#"(module App.HarnessMain)
(import App.CompilerMode)
(import Backend.Wasm.CompilerBase)

(defn text-starts-with-loop [text prefix idx len]
  (if (>= idx len)
    true
    (if (= (string-char-at text idx) (string-char-at prefix idx))
      (text-starts-with-loop text prefix (+ idx 1) len)
      false)))

(defn text-starts-with [text prefix]
  (let [len (string-length prefix)]
    (if (< (string-length text) len)
      false
      (text-starts-with-loop text prefix 0 len))))

(defn make-owner-state [found pair-idx decl-idx defn-ordinal decl-hash]
  (vector-push
    (vector-push
      (vector-push
        (vector-push
          (vector-push (vector-new 5) found)
          pair-idx)
        decl-idx)
      defn-ordinal)
    decl-hash))

(defn find-owner-in-decls [decls idx len ftable target defn-ordinal]
  (if (>= idx len)
    (make-owner-state 0 -1 -1 defn-ordinal 0)
    (let [decl (vector-get decls idx)]
      (if (= (vector-get decl 0) 20)
        (let [decl-hash (vector-get decl 1)
              func-idx (ftable-lookup ftable decl-hash)]
          (if (= func-idx target)
            (make-owner-state 1 0 idx defn-ordinal decl-hash)
            (find-owner-in-decls decls (+ idx 1) len ftable target (+ defn-ordinal 1))))
        (find-owner-in-decls decls (+ idx 1) len ftable target defn-ordinal)))))

(defn find-owner-in-pairs [pairs pair-idx len ftable target]
  (if (>= pair-idx len)
    (make-owner-state 0 -1 -1 -1 0)
    (let [pair (vector-get pairs pair-idx)
          decls (vector-get pair 1)
          state (find-owner-in-decls decls 0 (vector-length decls) ftable target 0)]
      (if (= (vector-get state 0) 1)
        (make-owner-state 1 pair-idx (vector-get state 2) (vector-get state 3) (vector-get state 4))
        (find-owner-in-pairs pairs (+ pair-idx 1) len ftable target)))))

(defn main []
  (let [cache-ref (ref-new (map-new))
        parse-count-ref (ref-new 0)
        _ (write-file "src/App/Seed.ls" "{escaped_seed_source}")
        pairs (compile-file-pairs-with-cache "src/App/Seed.ls" cache-ref parse-count-ref)
        reg-result (register-all-pairs pairs 0 (vector-length pairs) (ftable-new) 10)
        ftable (vector-get reg-result 0)
        owner (find-owner-in-pairs pairs 0 (vector-length pairs) ftable {target_idx})
        pair (vector-get pairs (vector-get owner 1))
        src (vector-get pair 0)]
    (do
      (print (vector-get owner 0))
      (print (vector-get owner 1))
      (print (vector-get owner 2))
      (print (vector-get owner 3))
      (print (vector-get owner 4))
      (print (if (text-starts-with src "(module Backend.Native.NativeCodegen)") 1 0))
      (print (if (text-starts-with src "(module Backend.Wasm.Compiler)") 1 0))
      (print (if (text-starts-with src "(module Backend.Wasm.CompilerBase)") 1 0))
      (print (if (text-starts-with src "(module Syntax.Parser)") 1 0))
      (print (if (text-starts-with src "(module App.Seed)") 1 0))
      (print (string-length src))
      0)))"#,
        escaped_seed_source = escaped_seed_source,
        target_idx = target_idx
    );
    let label = format!("linux-x86-actual-seed-owner-{target_idx}-diagnostic");
    let output = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        try_compile_and_run_selfhost_fixture_entry_with_dir_and_args(
            &label,
            SELFHOST_APP_MAIN_REPRESENTATIVE_MODULES,
            "src/App/HarnessMain.ls",
            &harness,
            &[],
        )
    })
    .expect("Linux x86 actual seed owner decl diagnostic 実行に失敗");
    let lines = parse_numeric_lines(&output);
    println!("Linux x86 actual seed owner {target_idx} lines: {lines:?}");
    assert_eq!(
        lines.first().copied(),
        Some(1),
        "指定 function index の owner decl が見つからない: target={target_idx} lines={lines:?}"
    );
}

#[test]
#[ignore]
fn test_e2e_selfhost_main_linux_x86_actual_seed_entry_call_offsets_diagnostic() {
    let seed_source = linux_x86_representative_actual_stage23_seed_source();
    let escaped_seed_source = escape_lsharp_string(&seed_source);
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/Seed.ls" "{escaped_seed_source}")
            (compile-file-functions-payload-with-cache "src/App/Seed.ls" 10 cache-ref parse-count-ref))"#
    );
    let harness = format!(
        r#"(module App.HarnessMain)
	(import App.CompilerMode)
	(import Backend.Native.NativeTarget)
	(import Backend.Native.NativeCodegen)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn push-import-placeholders [idx count result]
  (if (>= idx count)
    result
    (push-import-placeholders
      (+ idx 1)
      count
      (vector-push result (make-function-meta 0 0 (vector-new 0))))))

(defn append-vector-loop [dst src idx len]
  (if (>= idx len)
    dst
    (append-vector-loop
      (vector-push dst (vector-get src idx))
      src
      (+ idx 1)
      len)))

(defn call-target-offset [operand starts import-count import-stub-offset function-start-base]
  (if (< operand import-count)
    (- (x86-import-ret-stub-offset import-stub-offset import-count operand) function-start-base)
    (- (vector-get starts (- operand import-count)) function-start-base)))

(defn print-entry-call-offsets [ir functions starts import-count import-stub-offset function-start-base offsets idx len depth]
  (if (>= idx len)
    0
    (let [instr (vector-get ir idx)
          opcode (vector-get instr 0)
          operand (vector-get instr 1)
          current-offset (vector-get offsets idx)
          next-depth (apply-stack-delta depth (opcode-stack-delta opcode operand functions))]
      (if (and (>= current-offset 250) (< current-offset 380))
          (do
            (print idx)
            (print opcode)
            (print operand)
            (print depth)
            (print current-offset)
            (print (native-instr-size-x86 opcode operand functions depth))
            (if (= opcode 40)
              (do
                (print (native-function-param-count (vector-get functions operand)))
                (print (call-target-offset operand starts import-count import-stub-offset function-start-base)))
              (do
                (print -1)
                (print -1)))
            (print-entry-call-offsets ir functions starts import-count import-stub-offset function-start-base offsets (+ idx 1) len next-depth))
          (print-entry-call-offsets ir functions starts import-count import-stub-offset function-start-base offsets (+ idx 1) len next-depth)))))

(defn x86-param-spill-prefix-size [param-count]
  (if (>= param-count 20)
    (native-param-spill-bytes-x86-twenty-plus param-count)
    (if (> param-count 6)
      (+ 53 (* (- param-count 7) 11))
      (if (= param-count 6)
        42
        (if (= param-count 5)
          35
          (if (= param-count 4)
            28
            (if (= param-count 3)
              21
              (if (= param-count 2)
                14
                (if (= param-count 1) 7 0)))))))))

(defn main []
  (let [cache-ref (ref-new (map-new))
        parse-count-ref (ref-new 0)
        payload {payload_expr}
        functions (vector-get payload 0)
        main-func-idx (vector-get payload 1)
	        callables (append-vector-loop (push-import-placeholders 0 10 (vector-new 32)) functions 0 (vector-length functions))
	        target (make-target 3)
	        native-callables (normalize-selfhost-native-function-metas-for-target callables target)
        starts (collect-callable-function-starts-x86 native-callables 10)
        import-stub-offset (callable-user-total-size-x86 native-callables 10)
        function-start-base (vector-get starts (- main-func-idx 10))
        func (vector-get native-callables main-func-idx)
        ir (native-function-ir func)
        frame-base-slot-count
          (native-frame-base-slot-count
            ir
            (+ (+ (native-function-param-count func) (native-function-local-count func)) 1))
        body-offset (+
          (+ 0 4)
          (+
            (if (> (native-local-stack-bytes-with-window
                     ir
                     (+ (+ (native-function-param-count func) (native-function-local-count func)) 1)
                     native-callables)
                  0)
              7
              0)
            (x86-param-spill-prefix-size (native-function-param-count func))))
        offsets (collect-native-bundle-offsets-x86 ir native-callables body-offset)]
    (do
      (print main-func-idx)
      (print function-start-base)
      (print (native-function-size-x86 func native-callables))
      (print-entry-call-offsets ir native-callables starts 10 import-stub-offset function-start-base offsets 0 (vector-length ir) 0))))"#,
        payload_expr = payload_expr
    );
    let output = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        try_compile_and_run_selfhost_fixture_entry_with_dir_and_args(
            "linux-x86-actual-seed-entry-call-offsets-diagnostic",
            SELFHOST_APP_MAIN_REPRESENTATIVE_MODULES,
            "src/App/HarnessMain.ls",
            &harness,
            &[],
        )
    })
    .expect("Linux x86 actual seed entry call offsets diagnostic 実行に失敗");
    let lines = parse_numeric_lines(&output);
    println!("Linux x86 actual seed entry call offset lines: {lines:?}");
    assert!(
        !lines.is_empty(),
        "Linux x86 actual seed entry call offsets diagnostic 出力が空"
    );
}

fn assert_x86_function_size_matches_generated_length_for_seed(
    label: &str,
    seed_source: String,
    segmented_layout: bool,
) {
    let escaped_seed_source = escape_lsharp_string(&seed_source);
    let segmented_layout_flag = if segmented_layout { 1 } else { 0 };
    let payload_expr = format!(
        r#"(do
            (write-file "src/App/Seed.ls" "{escaped_seed_source}")
            (compile-file-functions-payload-with-cache "src/App/Seed.ls" 10 cache-ref parse-count-ref))"#
    );
    let harness = format!(
        r#"(module App.HarnessMain)
(import App.CompilerMode)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn push-import-placeholders [idx count result]
  (if (>= idx count)
    result
    (push-import-placeholders
      (+ idx 1)
      count
      (vector-push result (make-function-meta 0 0 (vector-new 0))))))

(defn append-vector-loop [dst src idx len]
  (if (>= idx len)
    dst
    (append-vector-loop
      (vector-push dst (vector-get src idx))
      src
      (+ idx 1)
      len)))

(defn pad-byte-vector-to-length-range [bytes start end]
  (if (>= start end)
    bytes
    (let [width (- end start)]
      (if (= width 1)
        (vector-push bytes 144)
        (do
          (root_push bytes)
          (let [mid (+ start (/ width 2))
                left (pad-byte-vector-to-length-range bytes start mid)]
            (do
              (root_push left)
              (let [right (pad-byte-vector-to-length-range left mid end)]
                (do
                  (root_pop)
                  (root_pop)
                  right)))))))))

(defn pad-byte-vector-to-length [bytes target-len]
  (pad-byte-vector-to-length-range bytes (vector-length bytes) target-len))

	(defn check-instr-sizes [ir functions starts import-count import-stub-offset frame-base-slot-count meta offsets idx len depth]
	  (if (>= idx len)
	    0
	    (let [instr (vector-get ir idx)
	          opcode (vector-get instr 0)
          operand (vector-get instr 1)
          expected (native-instr-size-x86 opcode operand functions depth)
          native (if (= (is-control-opcode opcode) 1)
                   (emit-control-instr-x86 ir meta offsets idx)
                   (codegen-ir-instr-bundle-x86-with-import-count opcode operand (vector-get offsets idx) starts functions import-count import-stub-offset frame-base-slot-count depth))
          actual (vector-length native)]
	      (if (!= expected actual)
	        (do
	          (print 777000)
	          (print idx)
	          (print opcode)
	          (print operand)
	          (print depth)
	          (print expected)
	          (print actual)
	          1)
	        (check-instr-sizes ir functions starts import-count import-stub-offset frame-base-slot-count meta offsets (+ idx 1) len (apply-stack-delta depth (opcode-stack-delta opcode operand functions)))))))

(defn check-function-sizes [functions starts result import-count import-stub-offset idx len]
  (if (>= idx len)
    (do
      (print -1)
      (print (vector-length (ref-get result)))
      0)
    (let [func-idx (+ idx import-count)
          func (vector-get functions func-idx)
           expected-start (vector-get starts idx)
           actual-start (vector-length (ref-get result))
           expected-size (native-function-size-x86 func functions)
           emit-starts starts
           emit-import-offset import-stub-offset]
	      (do
	        (if (= {segmented_layout_flag} 1)
	          (let [layout (make-x86-function-emit-layout import-count emit-import-offset expected-start actual-start)]
            (do
              (root_push layout)
              (generate-native-function-x86-64-bundle-with-layout
                func
                result
                emit-starts
                functions
                layout)
              (root_pop)))
	          (generate-native-function-x86-64-bundle-with-import-count
	            func
	            result
	            emit-starts
	            functions
	            import-count
	            emit-import-offset))
	        (let [actual-after (vector-length (ref-get result))
	              actual-size (- actual-after actual-start)
	              ir-len (vector-length (native-function-ir func))
	              size-status (if (> ir-len 4096)
	                            (if (>= expected-size actual-size) 0 1)
	                            (if (= expected-size actual-size) 0 1))
	              instr-status (check-instr-sizes
	                (native-function-ir func)
	                functions
	                emit-starts
	                import-count
	                emit-import-offset
	                (native-frame-base-slot-count
	                  (native-function-ir func)
	                  (+ (+ (native-function-param-count func) (native-function-local-count func)) 1))
	                (scan-control-flow-meta (native-function-ir func))
	                (collect-native-bundle-offsets-x86
	                  (native-function-ir func)
	                  functions
	                  (+ (+ expected-start 4)
	                    (+ (if (> (native-local-stack-bytes-with-window
	                                  (native-function-ir func)
	                                  (+ (+ (native-function-param-count func) (native-function-local-count func)) 1)
	                                  functions)
	                               0)
	                         7
	                         0)
	                       (if (>= (native-function-param-count func) 20)
	                         (native-param-spill-bytes-x86-twenty-plus (native-function-param-count func))
	                         (if (> (native-function-param-count func) 6)
	                           (+ 53 (* (- (native-function-param-count func) 7) 11))
	                           (if (= (native-function-param-count func) 6)
	                             42
	                             (if (= (native-function-param-count func) 5)
	                               35
	                               (if (= (native-function-param-count func) 4)
	                                 28
	                                 (if (= (native-function-param-count func) 3)
	                                   21
	                                   (if (= (native-function-param-count func) 2)
	                                     14
	                                     (if (= (native-function-param-count func) 1) 7 0)))))))))))
	                0
	                (vector-length (native-function-ir func))
	                0)
	              padding-status (if (if (= size-status 0) (> expected-size actual-size) false)
	                               (do
	                                 (ref-set result (pad-byte-vector-to-length (ref-get result) (+ actual-start expected-size)))
	                                 0)
	                               0)]
	          (if (or (or (!= expected-start actual-start) (!= size-status 0)) (!= instr-status 0))
	            (do
	              (print func-idx)
	              (print expected-start)
              (print actual-start)
              (print expected-size)
              (print actual-size)
              (print (native-function-param-count func))
              (print (native-function-local-count func))
              (print ir-len)
              (print (native-local-stack-bytes-with-window
                (native-function-ir func)
                (+ (+ (native-function-param-count func) (native-function-local-count func)) 1)
                functions))
              0)
            (check-function-sizes functions starts result import-count import-stub-offset (+ idx 1) len)))))))

	(defn main []
	  (let [cache-ref (ref-new (map-new))
	        parse-count-ref (ref-new 0)
	        payload {payload_expr}
	        functions (vector-get payload 0)
	        callables (append-vector-loop (push-import-placeholders 0 10 (vector-new 32)) functions 0 (vector-length functions))
	        target (make-target 3)
	        native-callables (normalize-selfhost-native-function-metas-for-target callables target)
	        starts (collect-callable-function-starts-x86 native-callables 10)
        import-stub-offset (callable-user-total-size-x86 native-callables 10)
        result (ref-new (vector-new 128))]
    (check-function-sizes native-callables starts result 10 import-stub-offset 0 (vector-length starts))))"#,
        payload_expr = payload_expr,
        segmented_layout_flag = segmented_layout_flag
    );
    let label = label.to_string();
    let output = run_with_expanded_stack(NATIVE_HARNESS_STACK_BYTES, move || {
        try_compile_and_run_selfhost_fixture_entry_with_dir_and_args(
            &label,
            SELFHOST_APP_MAIN_REPRESENTATIVE_MODULES,
            "src/App/HarnessMain.ls",
            &harness,
            &[],
        )
    })
    .expect("representative x86 function size diagnostic 実行に失敗");
    let lines = parse_numeric_lines(&output);
    assert_eq!(
        lines.first().copied(),
        Some(-1),
        "x86 function size mismatch diagnostic: {lines:?}"
    );
}

/// NATIVE-LINUX-X86-03: hostgen artifact は Linux target descriptor を指定した selfhost emit-native 由来であること。
#[test]
