#[test]
#[ignore = "diagnostic: V2-13a-5 Linux x86 entry metadata map-new rel32 correlation"]
fn test_e2e_linux_x86_actual_function_metadata_map_new_rel32_correlation() {
    let metadata_path = std::env::var_os("LSHARP_NATIVE_LINUX_X86_FUNCTION_METADATA").expect(
        "LSHARP_NATIVE_LINUX_X86_FUNCTION_METADATA に stage1/stage2 metadata txt を指定すること",
    );
    let metadata_path = workspace_root_relative_path(std::path::PathBuf::from(metadata_path));
    let metadata = std::fs::read_to_string(&metadata_path).unwrap_or_else(|e| {
        panic!(
            "Linux x86 function metadata 読み込み失敗 ({}): {e}",
            metadata_path.display()
        )
    });
    let metadata_rows = parse_linux_x86_function_segment_metadata_rows(&metadata);
    let direct_rows = parse_x86_map_new_direct_replay_rows(&metadata);
    let map_new_row = metadata_rows
        .iter()
        .find(|row| row.opcode == 60)
        .expect("metadata に opcode60 map-new row が存在すること");
    let direct_row = direct_rows
        .iter()
        .find(|row| {
            row.instr_idx == map_new_row.instr_idx
                && row.opcode == map_new_row.opcode
                && row.depth == map_new_row.depth
                && row.offset == map_new_row.offset
                && row.size == map_new_row.size
        })
        .expect("metadata に map-new direct replay row が存在すること");
    let emitted_relative_target = x86_metadata_row_rel32_target(map_new_row)
        .expect("map-new emitted bytes は rel32 call を含むこと");
    let emitted_absolute_target = direct_row.emit_start_base + emitted_relative_target;
    let expected_direct_rel = direct_row.helper_target - (direct_row.offset + 5);

    assert_eq!(
        emitted_absolute_target,
        direct_row.helper_target,
        "stage-generated map-new emitted bytes の rel32 target は helper target と一致するべき: metadata={} row={map_new_row:?} direct={direct_row:?}",
        metadata_path.display()
    );
    assert_eq!(
        direct_row.direct_call_rel,
        expected_direct_rel,
        "map-new direct replay の rel32 計算が helper target と一致しない: metadata={} row={map_new_row:?} direct={direct_row:?}",
        metadata_path.display()
    );
    println!(
        "Linux x86 map-new rel32 correlation: metadata={} emitted_relative_target={} emitted_absolute_target={} helper_target={} direct_call_rel={} direct_target={} row={map_new_row:?} direct={direct_row:?}",
        metadata_path.display(),
        emitted_relative_target,
        emitted_absolute_target,
        direct_row.helper_target,
        direct_row.direct_call_rel,
        direct_row.direct_target
    );
}

#[test]
#[ignore = "diagnostic: V2-13a-5 Linux x86 function metadata user call rel32 correlation"]
fn test_e2e_linux_x86_actual_function_metadata_user_call_rel32_correlation() {
    let metadata_path = std::env::var_os("LSHARP_NATIVE_LINUX_X86_FUNCTION_METADATA").expect(
        "LSHARP_NATIVE_LINUX_X86_FUNCTION_METADATA に stage1/stage2 metadata txt を指定すること",
    );
    let metadata_path = workspace_root_relative_path(std::path::PathBuf::from(metadata_path));
    let metadata = std::fs::read_to_string(&metadata_path).unwrap_or_else(|e| {
        panic!(
            "Linux x86 function metadata 読み込み失敗 ({}): {e}",
            metadata_path.display()
        )
    });
    let metadata_rows = parse_linux_x86_function_segment_metadata_rows(&metadata);
    let direct_rows = parse_x86_user_call_direct_replay_rows(&metadata);
    assert!(
        !direct_rows.is_empty(),
        "Linux x86 function metadata に opcode 40 user call direct replay row が無い: path={}",
        metadata_path.display()
    );

    let mut compared_rel32_rows = 0usize;
    for direct_row in &direct_rows {
        assert_eq!(direct_row.opcode, 40);
        assert_eq!(
            direct_row.call_rel,
            direct_row.target_offset - (direct_row.offset + direct_row.call_next_offset),
            "opcode 40 direct replay row の call-rel が target/current offset と一致しない: row={direct_row:?}"
        );
        assert_eq!(
            direct_row.direct_target, direct_row.target_offset,
            "opcode 40 direct replay row の rel32 target が target-offset と一致しない: row={direct_row:?}"
        );
        let metadata_row = metadata_rows
            .iter()
            .find(|row| {
                row.instr_idx == direct_row.instr_idx
                    && row.opcode == direct_row.opcode
                    && row.operand == direct_row.operand
                    && row.depth == direct_row.depth
                    && row.offset == direct_row.offset
                    && row.size == direct_row.size
            })
            .unwrap_or_else(|| {
                panic!(
                    "opcode 40 direct replay row に対応する metadata row が無い: row={direct_row:?}"
                )
            });
        if let Some(emitted_target) = x86_metadata_row_rel32_target(metadata_row) {
            compared_rel32_rows += 1;
            assert_eq!(
                emitted_target, direct_row.direct_target,
                "opcode 40 emitted bytes と direct replay の rel32 target が一致しない: metadata_row={metadata_row:?} direct_row={direct_row:?}"
            );
        }
    }
    assert!(
        compared_rel32_rows > 0,
        "Linux x86 function metadata の opcode 40 rows に first-8-byte rel32 call が無く、emitted/direct target を比較できなかった: path={} rows={direct_rows:?}",
        metadata_path.display()
    );
}

#[test]
#[ignore = "diagnostic: V2-13a-5 Linux x86 body-size recursive user-call target"]
fn test_e2e_linux_x86_actual_body_size_metadata_recursive_call_targets_self() {
    let metadata_path = std::env::var_os("LSHARP_NATIVE_LINUX_X86_FUNCTION_METADATA").expect(
        "LSHARP_NATIVE_LINUX_X86_FUNCTION_METADATA に body-size function metadata txt を指定すること",
    );
    let metadata_path = workspace_root_relative_path(std::path::PathBuf::from(metadata_path));
    let target_function_idx: i128 =
        std::env::var("LSHARP_NATIVE_LINUX_X86_BODY_SIZE_FUNCTION_INDEX")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(1802);
    let recursive_instr_idx: i128 =
        std::env::var("LSHARP_NATIVE_LINUX_X86_BODY_SIZE_RECURSIVE_INSTR_INDEX")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(73);
    let metadata = std::fs::read_to_string(&metadata_path).unwrap_or_else(|e| {
        panic!(
            "Linux x86 body-size metadata 読み込み失敗 ({}): {e}",
            metadata_path.display()
        )
    });
    let headers = parse_linux_x86_function_segment_metadata_headers(&metadata);
    let header = headers
        .iter()
        .find(|header| header.function_idx as i128 == target_function_idx)
        .unwrap_or_else(|| {
            panic!(
                "body-size metadata に target function header が無い: target={target_function_idx} path={} headers={headers:?}",
                metadata_path.display()
            )
        });
    let direct_rows = parse_x86_user_call_direct_replay_wide_rows(&metadata);
    let recursive_row = direct_rows
        .iter()
        .find(|row| row.instr_idx == recursive_instr_idx && row.opcode == 40)
        .unwrap_or_else(|| {
            panic!(
                "body-size metadata に recursive opcode 40 row が無い: instr={recursive_instr_idx} path={} rows={direct_rows:?}",
                metadata_path.display()
            )
        });

    println!(
        "Linux x86 body-size recursive call diagnostic: metadata={} header={header:?} row={recursive_row:?}",
        metadata_path.display()
    );
    assert_eq!(
        recursive_row.operand,
        target_function_idx,
        "x86-body-size-loop-ctx の自己再帰 call operand は current function を指すべき: metadata={} header={header:?} row={recursive_row:?}",
        metadata_path.display()
    );
    assert_eq!(
        recursive_row.target_offset,
        0,
        "x86-body-size-loop-ctx の自己再帰 call target は current function start 相対 0 を指すべき: metadata={} header={header:?} row={recursive_row:?}",
        metadata_path.display()
    );
}

#[test]
fn test_linux_x86_actual_transport_segment_table_maps_absolute_offsets() {
    let stdout = b"9000000005\n2\n11\n8\n9000000006\n9000000001\n5\n9000000002\n9000000010\n3\n513\n9000000010\n2\n1027\n9000000003\n0\n9000000004\n";
    let (layout, code_len, segments) = decode_linux_x86_actual_transport_code_segments(stdout);

    assert_eq!(layout.function_start_len, 2);
    assert_eq!(layout.main_func_idx, 11);
    assert_eq!(layout.entrypoint_offset, 8);
    assert_eq!(code_len, 5);
    assert_eq!(
        segments,
        vec![
            LinuxX86TransportCodeSegment {
                segment_index: 0,
                function_idx: Some(10),
                start: 0,
                len: 3,
                first_32_bytes: vec![1, 2, 0],
            },
            LinuxX86TransportCodeSegment {
                segment_index: 1,
                function_idx: Some(11),
                start: 3,
                len: 2,
                first_32_bytes: vec![3, 4],
            },
        ]
    );
    let hit = find_linux_x86_transport_segment_for_offset(&segments, 4)
        .expect("offset 4 は second segment に対応するべき");
    assert_eq!(hit.segment_index, 1);
    assert_eq!(hit.function_idx, Some(11));
    assert_eq!(4 - hit.start, 1);
}

#[test]
