fn assert_linux_x86_entry_map_ref_ref_prefix(
    bundle: &NativeEntrypointBundle,
    label: &str,
) -> Vec<X86Rel32CallSite> {
    let calls = collect_x86_entry_rel32_calls(bundle, 0..160);
    let suffix_distances = calls
        .iter()
        .map(|call| bundle.code_bytes.len() as i64 - call.target_offset)
        .collect::<Vec<_>>();
    assert!(
        calls.len() >= 3,
        "{label}: entry prefix に map-new/ref-new/ref-new helper calls が不足: entry={} code_len={} calls={calls:?} suffix_distances={suffix_distances:?} entry_window={}",
        bundle.entrypoint_offset,
        bundle.code_bytes.len(),
        byte_window_hex(&bundle.code_bytes, bundle.entrypoint_offset, 0, 192)
    );
    assert_eq!(
        suffix_distances[0], 296,
        "{label}: first helper call は map-new helper を指すべき: calls={calls:?} suffix_distances={suffix_distances:?}"
    );
    assert_eq!(
        suffix_distances[1], 747,
        "{label}: second helper call は ref-new helper を指すべき: calls={calls:?} suffix_distances={suffix_distances:?}"
    );
    assert_eq!(
        suffix_distances[2], 747,
        "{label}: third helper call は ref-new helper を指すべき: calls={calls:?} suffix_distances={suffix_distances:?}"
    );
    calls
}

#[test]
#[ignore = "diagnostic: V2-13a-5 Linux x86 stage2 entrypoint call windows/rel32 targets"]
fn test_e2e_linux_x86_actual_stage2_entrypoint_call_windows_diagnostic() {
    let stage2_dir = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE2_ARTIFACT_DIR").expect(
        "LSHARP_NATIVE_LINUX_X86_STAGE2_ARTIFACT_DIR に stage2 artifact dir を指定すること",
    );
    let stage2_dir = workspace_root_relative_path(std::path::PathBuf::from(stage2_dir));
    let stage2_bundle = read_linux_x86_stage_code_artifact_bundle(
        &stage2_dir,
        &["stage-code.bin", "stage2-code.bin"],
        &["stage-data.bin", "stage2-data.bin"],
    );
    let target_range = 0..stage2_bundle.code_bytes.len();
    let bootstrap_call = assert_x86_entrypoint_call_window(
        &stage2_bundle,
        "Linux x86 stage2 entry bootstrap helper call",
        8..16,
        target_range,
    );
    let stage2_prefix_calls = collect_x86_entry_rel32_calls(&stage2_bundle, 0..128);
    let stage2_entry_calls = collect_x86_entry_rel32_calls(&stage2_bundle, 0..1024);
    let stage1_dir_for_trace = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE1_ARTIFACT_DIR")
        .map(std::path::PathBuf::from)
        .map(workspace_root_relative_path);
    println!(
        "Linux x86 stage2 entrypoint diagnostic: dir={} entry={} code_len={} main_func_idx={} function_start_len={} bootstrap={bootstrap_call:?} prefix_calls={stage2_prefix_calls:?}",
        stage2_dir.display(),
        stage2_bundle.entrypoint_offset,
        stage2_bundle.code_bytes.len(),
        stage2_bundle.main_func_idx,
        stage2_bundle.function_start_len
    );

    if let Some(stage1_dir) = stage1_dir_for_trace.as_ref() {
        let stage1_bundle = read_linux_x86_stage_code_artifact_bundle(
            stage1_dir,
            &["stage1-code.bin", "stage-code.bin"],
            &["stage1-data.bin", "stage-data.bin"],
        );
        let stage1_prefix_calls = collect_x86_entry_rel32_calls(&stage1_bundle, 0..128);
        println!(
            "Linux x86 stage1/stage2 entrypoint comparison: stage1_dir={} stage1_entry={} stage1_code_len={} stage1_calls={stage1_prefix_calls:?} stage2_calls={stage2_prefix_calls:?}",
            stage1_dir.display(),
            stage1_bundle.entrypoint_offset,
            stage1_bundle.code_bytes.len()
        );
        assert!(
            stage2_prefix_calls.len() <= stage1_prefix_calls.len(),
            "stage2 entrypoint prefix call count が stage1 より増えている: stage1={stage1_prefix_calls:?} stage2={stage2_prefix_calls:?}"
        );
    }

    let trace_path = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE2_ENTRY_IR_TRACE")
        .map(std::path::PathBuf::from)
        .map(workspace_root_relative_path)
        .or_else(|| {
            stage1_dir_for_trace
                .as_ref()
                .map(|dir| dir.join("stage-entry-ir-trace.txt"))
                .filter(|path| path.exists())
        });
    let metadata_path = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE2_ENTRY_METADATA")
        .map(std::path::PathBuf::from)
        .map(workspace_root_relative_path)
        .or_else(|| {
            stage2_dir
                .parent()
                .map(|dir| dir.join("actual-stage2-metadata.txt"))
                .filter(|path| path.exists())
        });
    let trace_rows_with_source = if let Some(trace_path) = trace_path {
        Some((
            format!("trace:{}", trace_path.display()),
            read_x86_ir_call_trace_rows(&trace_path),
        ))
    } else {
        metadata_path.map(|metadata_path| {
            (
                format!("metadata:{}", metadata_path.display()),
                read_x86_ir_call_trace_rows_from_metadata(&metadata_path),
            )
        })
    };
    if let Some((trace_source, trace_rows)) = trace_rows_with_source {
        assert_x86_ir_call_trace_matches_entry_calls(&stage2_bundle, &trace_rows);
        assert_x86_call_targets_do_not_skip_rex_stack_restore_prefix(
            "Linux x86 stage2 entrypoint rel32 target diagnostic",
            &stage2_bundle,
            &stage2_entry_calls,
            &trace_rows,
        );
        println!(
            "Linux x86 stage2 IR opcode/metadata bytes/rel32 trace correlated: source={trace_source} rows={trace_rows:?}"
        );
    } else {
        assert_x86_call_targets_do_not_skip_rex_stack_restore_prefix(
            "Linux x86 stage2 entrypoint rel32 target diagnostic",
            &stage2_bundle,
            &stage2_entry_calls,
            &[],
        );
        println!(
            "Linux x86 stage2 IR trace/entry metadata 未指定: LSHARP_NATIVE_LINUX_X86_STAGE2_ENTRY_IR_TRACE または LSHARP_NATIVE_LINUX_X86_STAGE2_ENTRY_METADATA を指定すると opcode 40/60/56 などの rel32 row / emitted bytes / rel32 target を同一 window で照合する"
        );
    }
}

#[test]
#[ignore = "diagnostic: V2-13a-5 Linux x86 actual stage2 transport segment table"]
fn test_e2e_linux_x86_actual_stage2_transport_segment_table_diagnostic() {
    let stdout_path = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE2_STDOUT")
        .expect("LSHARP_NATIVE_LINUX_X86_STAGE2_STDOUT に actual-stage2-stdout.txt を指定すること");
    let stdout_path = workspace_root_relative_path(std::path::PathBuf::from(stdout_path));
    let target_offset: usize = std::env::var("LSHARP_NATIVE_LINUX_X86_TARGET_OFFSET")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(3_321_766);
    let stdout = std::fs::read(&stdout_path).unwrap_or_else(|e| {
        panic!(
            "actual-stage2 stdout 読み込み失敗 ({}): {e}",
            stdout_path.display()
        )
    });
    let (layout, code_len, segments) = decode_linux_x86_actual_transport_code_segments(&stdout);
    let hit = find_linux_x86_transport_segment_for_offset(&segments, target_offset)
        .unwrap_or_else(|| panic!("target offset {target_offset} に対応する segment が無い"));
    println!(
        "Linux x86 actual stage2 transport segment: stdout={} target_offset={} layout={layout:?} code_len={} segment={hit:?} relative_offset={}",
        stdout_path.display(),
        target_offset,
        code_len,
        target_offset - hit.start
    );

    if let Some(stage2_dir) = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE2_ARTIFACT_DIR") {
        let stage2_dir = workspace_root_relative_path(std::path::PathBuf::from(stage2_dir));
        let stage2_bundle = read_linux_x86_stage_code_artifact_bundle(
            &stage2_dir,
            &["stage-code.bin", "stage2-code.bin"],
            &["stage-data.bin", "stage2-data.bin"],
        );
        assert_eq!(
            stage2_bundle.code_bytes.len(),
            code_len,
            "decoded stdout code_len と stage2-debug code bytes 長が一致しない"
        );
        println!(
            "Linux x86 actual stage2 transport byte windows: segment_start={} target={} segment_window={} target_window={}",
            hit.start,
            target_offset,
            byte_window_hex(&stage2_bundle.code_bytes, hit.start, 0, 96),
            byte_window_hex(&stage2_bundle.code_bytes, target_offset, 32, 64)
        );
    }
}

#[test]
#[ignore = "regression: V2-13a-5 Linux x86 stage2 entrypoint map-new/ref-new prefix"]
fn test_e2e_linux_x86_actual_stage2_entrypoint_map_new_ref_new_prefix_regression() {
    let stage2_dir = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE2_ARTIFACT_DIR").expect(
        "LSHARP_NATIVE_LINUX_X86_STAGE2_ARTIFACT_DIR に stage2 artifact dir を指定すること",
    );
    let stage2_dir = workspace_root_relative_path(std::path::PathBuf::from(stage2_dir));
    let stage2_bundle = read_linux_x86_stage_code_artifact_bundle(
        &stage2_dir,
        &["stage-code.bin", "stage2-code.bin"],
        &["stage-data.bin", "stage2-data.bin"],
    );

    if let Some(stage1_dir) = std::env::var_os("LSHARP_NATIVE_LINUX_X86_STAGE1_ARTIFACT_DIR") {
        let stage1_dir = workspace_root_relative_path(std::path::PathBuf::from(stage1_dir));
        let stage1_bundle = read_linux_x86_stage_code_artifact_bundle(
            &stage1_dir,
            &["stage1-code.bin", "stage-code.bin"],
            &["stage1-data.bin", "stage-data.bin"],
        );
        let stage1_calls =
            assert_linux_x86_entry_map_ref_ref_prefix(&stage1_bundle, "Linux x86 stage1");
        println!(
            "Linux x86 stage1 entry map/ref/ref prefix: dir={} calls={stage1_calls:?}",
            stage1_dir.display()
        );
    }

    let stage2_calls =
        assert_linux_x86_entry_map_ref_ref_prefix(&stage2_bundle, "Linux x86 stage2");
    println!(
        "Linux x86 stage2 entry map/ref/ref prefix: dir={} calls={stage2_calls:?}",
        stage2_dir.display()
    );
}

/// V2-09: actual self-regeneration で得た native stage 生成物を differential input として扱えること。
#[test]
#[ignore]
fn test_e2e_wasm_native_differential_uses_actual_self_regenerated_stage_artifacts() {
    if !host_native_exec_supported() {
        return;
    }

    let (stage2_bundle, stage2_input, stage3_bundle, stage3_input) =
        run_actual_native_self_regeneration_stage23_pair()
            .expect("actual self-regenerated native stage artifact を回収できない");

    let stage2_artifact = observe_native_host_artifact_bundle(&stage2_bundle);
    let stage3_artifact = observe_native_host_artifact_bundle(&stage3_bundle);
    assert_eq!(
        stage2_artifact, stage3_artifact,
        "V2-09 differential input: actual stage2/stage3 native artifact hash が一致しない"
    );
    assert_eq!(
        stage2_input, stage3_input,
        "V2-09 differential input: actual stage2/stage3 transport payload が一致しない"
    );
    assert!(
        stage2_input.entrypoint_offset < stage2_input.code_bytes.len(),
        "V2-09 differential input: stage2 entrypoint が code bytes 範囲外"
    );
    assert!(
        !stage2_input.code_bytes.is_empty() && !stage2_input.data_bytes.is_empty(),
        "V2-09 differential input: actual stage native code/data が空"
    );
    assert_eq!(
        stage2_bundle.exit_code, 0,
        "V2-09 differential input: stage2 native 実行が成功すること"
    );
    assert_eq!(
        stage3_bundle.exit_code, 0,
        "V2-09 differential input: stage3 native 実行が成功すること"
    );
}

// =============================================================================
// ZERO-DIFF サンプル: Wasm 出力と native exit code の一致検証
//
// 前提: L# の `(defn main [] N)` 相当プログラムにおいて
//   - Wasm パス: `(print N)` → stdout "N"
//   - Native パス: IR {opcode=1, operand=N} → exit code N
// の両者が整数 N で一致することを示す。
// =============================================================================

/// host-target 向けに定数 N を返す AArch64 バイト列を生成して実行し、exit code を返す。
fn native_exit_code_for_const(n: u32) -> i32 {
    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn print-bytes [bytes idx len]
  (if (>= idx len)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) len))))

(defn main []
  (let [instr (vector-push (vector-push (vector-new 2) 1) {n})
        ir (vector-push (vector-new 1) instr)
        target (host-target)
        code (emit-native ir target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
        n = n
    );
    let code_bytes = run_native_codegen_host_bytes_harness(&source);
    assert!(
        !code_bytes.is_empty(),
        "native const {}: コードバイト列が空",
        n
    );
    link_and_run_native_host_binary(&code_bytes)
        .unwrap_or_else(|e| panic!("native const {}: リンク・実行失敗: {}", n, e))
}

fn native_exit_code_for_const_sequence(values: &[u32]) -> i32 {
    assert!(
        !values.is_empty(),
        "const sequence: 少なくとも 1 個の値が必要"
    );

    let mut bindings = String::new();
    for (idx, value) in values.iter().enumerate() {
        bindings.push_str(&format!(
            "        instr{idx} (vector-push (vector-push (vector-new 2) 3) {value})\n",
        ));
        if idx == 0 {
            bindings.push_str(&format!(
                "        ir0 (vector-push (vector-new {len}) instr0)\n",
                len = values.len()
            ));
        } else {
            bindings.push_str(&format!(
                "        ir{idx} (vector-push ir{prev} instr{idx})\n",
                prev = idx - 1
            ));
        }
    }

    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn print-bytes [bytes idx len]
  (if (>= idx len)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) len))))

(defn main []
  (let [
{bindings}        ir ir{last_idx}
        target (host-target)
        code (emit-native ir target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
        bindings = bindings,
        last_idx = values.len() - 1
    );

    let code_bytes = run_native_codegen_host_bytes_harness(&source);
    assert!(
        !code_bytes.is_empty(),
        "native const sequence {:?}: コードバイト列が空",
        values
    );
    link_and_run_native_host_binary(&code_bytes).unwrap_or_else(|e| {
        panic!(
            "native const sequence {:?}: リンク・実行失敗: {}",
            values, e
        )
    })
}

fn native_exit_code_for_const_sequence_after_drops(values: &[u32], drop_count: usize) -> i32 {
    assert!(
        !values.is_empty(),
        "const sequence after drops: 少なくとも 1 個の値が必要"
    );
    assert!(
        drop_count < values.len(),
        "const sequence after drops: drop 回数 {} は値数 {} 未満である必要がある",
        drop_count,
        values.len()
    );

    let mut bindings = String::new();
    for (idx, value) in values.iter().enumerate() {
        bindings.push_str(&format!(
            "        instr{idx} (vector-push (vector-push (vector-new 2) 3) {value})\n",
        ));
        if idx == 0 {
            bindings.push_str(&format!(
                "        ir0 (vector-push (vector-new {len}) instr0)\n",
                len = values.len() + drop_count
            ));
        } else {
            bindings.push_str(&format!(
                "        ir{idx} (vector-push ir{prev} instr{idx})\n",
                prev = idx - 1
            ));
        }
    }

    let mut last_idx = values.len() - 1;
    for drop_idx in 0..drop_count {
        let instr_idx = values.len() + drop_idx;
        bindings.push_str(&format!("        instr{instr_idx} (make-instr 44 0)\n",));
        bindings.push_str(&format!(
            "        ir{instr_idx} (vector-push ir{prev} instr{instr_idx})\n",
            prev = last_idx
        ));
        last_idx = instr_idx;
    }

    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn print-bytes [bytes idx len]
  (if (>= idx len)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) len))))

(defn main []
  (let [
{bindings}        ir ir{last_idx}
        func (make-function-meta 0 0 ir)
        functions (vector-push (vector-new 1) func)
        target (host-target)
        code (emit-native-function-meta-bundle functions target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
        bindings = bindings,
        last_idx = last_idx
    );

    let code_bytes = run_native_codegen_host_bytes_harness(&source);
    assert!(
        !code_bytes.is_empty(),
        "native const sequence {:?} after {} drops: コードバイト列が空",
        values,
        drop_count
    );
    link_and_run_native_host_binary(&code_bytes).unwrap_or_else(|e| {
        panic!(
            "native const sequence {:?} after {} drops: リンク・実行失敗: {}",
            values, drop_count, e
        )
    })
}

fn native_exit_code_for_direct_call_sum(values: &[u32]) -> i32 {
    assert!(
        !values.is_empty(),
        "direct call sum: 少なくとも 1 個の値が必要"
    );

    let mut caller_bindings = String::new();
    for (idx, value) in values.iter().enumerate() {
        if idx == 0 {
            caller_bindings.push_str(&format!(
                "        caller-ir0 (vector-push (vector-new {len}) (make-instr 3 {value}))\n",
                len = values.len() + 1
            ));
        } else {
            caller_bindings.push_str(&format!(
                "        caller-ir{idx} (vector-push caller-ir{prev} (make-instr 3 {value}))\n",
                prev = idx - 1
            ));
        }
    }

    let mut callee_bindings = format!(
        "        callee-ir0 (vector-push (vector-new {len}) (make-local-get 0))\n",
        len = values.len() * 2 - 1
    );
    let mut callee_last = 0usize;
    for idx in 1..values.len() {
        let get_idx = callee_last + 1;
        let add_idx = callee_last + 2;
        callee_bindings.push_str(&format!(
            "        callee-ir{get_idx} (vector-push callee-ir{prev} (make-local-get {idx}))\n",
            prev = callee_last
        ));
        callee_bindings.push_str(&format!(
            "        callee-ir{add_idx} (vector-push callee-ir{get_idx} (make-instr 24 0))\n",
        ));
        callee_last = add_idx;
    }

    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn print-bytes [bytes idx len]
  (if (>= idx len)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) len))))

(defn main []
  (let [
{caller_bindings}{callee_bindings}        caller-ir (vector-push caller-ir{caller_last} (make-call 1))
        callee-ir callee-ir{callee_last}
        caller (make-function-meta 0 0 caller-ir)
        callee (make-function-meta {param_count} 0 callee-ir)
        functions (vector-push (vector-push (vector-new 2) caller) callee)
        target (host-target)
        code (emit-native-function-meta-bundle functions target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
        caller_bindings = caller_bindings,
        callee_bindings = callee_bindings,
        caller_last = values.len() - 1,
        callee_last = callee_last,
        param_count = values.len()
    );

    let code_bytes = run_native_codegen_host_bytes_harness(&source);
    assert!(
        !code_bytes.is_empty(),
        "native direct call sum {:?}: コードバイト列が空",
        values
    );
    link_and_run_native_host_binary(&code_bytes).unwrap_or_else(|e| {
        panic!(
            "native direct call sum {:?}: リンク・実行失敗: {}",
            values, e
        )
    })
}

fn native_exit_code_for_direct_call_local_get(values: &[u32], local_idx: usize) -> i32 {
    assert!(
        !values.is_empty(),
        "direct call local.get: 少なくとも 1 個の値が必要"
    );
    assert!(
        local_idx < values.len(),
        "direct call local.get: local index {} が引数数 {} を超えている",
        local_idx,
        values.len()
    );

    let mut caller_bindings = String::new();
    for (idx, value) in values.iter().enumerate() {
        if idx == 0 {
            caller_bindings.push_str(&format!(
                "        caller-ir0 (vector-push (vector-new {len}) (make-instr 3 {value}))\n",
                len = values.len() + 1
            ));
        } else {
            caller_bindings.push_str(&format!(
                "        caller-ir{idx} (vector-push caller-ir{prev} (make-instr 3 {value}))\n",
                prev = idx - 1
            ));
        }
    }

    let source = format!(
        r#"(module Main)
(import Backend.Native.NativeTarget)
(import Backend.Native.NativeCodegen)
(import IR.IR)

(defn make-function-meta [param-count local-count ir]
  (vector-push
    (vector-push
      (vector-push (vector-new 3) param-count)
      local-count)
    ir))

(defn print-bytes [bytes idx len]
  (if (>= idx len)
    0
    (do
      (print (vector-get bytes idx))
      (print-bytes bytes (+ idx 1) len))))

(defn main []
  (let [
{caller_bindings}        caller-ir (vector-push caller-ir{caller_last} (make-call 1))
        callee-ir (vector-push (vector-new 1) (make-local-get {local_idx}))
        caller (make-function-meta 0 0 caller-ir)
        callee (make-function-meta {param_count} 0 callee-ir)
        functions (vector-push (vector-push (vector-new 2) caller) callee)
        target (host-target)
        code (emit-native-function-meta-bundle functions target)]
    (do
      (print-bytes code 0 (vector-length code))
      0)))"#,
        caller_bindings = caller_bindings,
        caller_last = values.len() - 1,
        local_idx = local_idx,
        param_count = values.len()
    );

    let code_bytes = run_native_codegen_host_bytes_harness(&source);
    assert!(
        !code_bytes.is_empty(),
        "native direct call local.get {} for {:?}: コードバイト列が空",
        local_idx,
        values
    );
    link_and_run_native_host_binary(&code_bytes).unwrap_or_else(|e| {
        panic!(
            "native direct call local.get {} for {:?}: リンク・実行失敗: {}",
            local_idx, values, e
        )
    })
}

/// ZERO-DIFF-01: const 0 — Wasm stdout と native exit code がともに 0
#[test]
#[ignore]
fn test_e2e_zero_diff_const_0() {
    if !host_native_exec_supported() {
        return;
    }

    let wasm_output = compile_and_run("(defn main [] (do (print 0) 0))");
    assert_eq!(wasm_output.trim(), "0", "Wasm: const 0 を print すること");

    let exit_code = native_exit_code_for_const(0);
    assert_eq!(exit_code, 0, "Native: const 0 → exit code 0");

    assert_eq!(
        wasm_output.trim().parse::<i32>().unwrap(),
        exit_code,
        "ZERO-DIFF: Wasm stdout と native exit code が一致すること (const 0)"
    );
}

